    {
      "path": "packages/dsh-sieve/src/index.ts",
      "content": "/**\n * dsh-sieve: token-saving judgment plugins for DeepSeek Harness.\n *\n * The `sieve` service binds the judgment kernel to profile configuration, a\n * dedicated judge model (Jev or Laya; never the session's own model) and the\n * durable ledger. Without a judge model it changes nothing. The MVP admits tool\n * output through bounded post-execute judgments and archived originals;\n * history forgetting and task-based skill catalogs use native session events.\n *\n * sieve must not append its own Session event types: at the pinned DSH version\n * a stored log containing an unknown event without the `ignorable` envelope\n * marker refuses to resume, and `Session.append` cannot set that marker\n * (tests/contracts/plugin-event-restore.spec.ts). State is derived from native\n * events or kept in `ctx.storage`.\n * @module dsh-sieve\n */\n\nimport { Service } from '@deepseek-ai/cordis'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-storage-domain'\nimport type {} from '@deepseek-ai/dsh-token-meter'\nimport type { DecisionMode } from './judge/decision.ts'\nimport { DecisionEngine } from './judge/engine.ts'\nimport { Inflight } from './judge/inflight.ts'\nimport { Judge } from './judge/judge.ts'\nimport type { JudgeLike } from './judge/judge.ts'\nimport type { LedgerAnnotation, LedgerRecord } from './judge/ledger.ts'\nimport { LayaJudgeProvider } from './judge/providers/laya.ts'\nimport { SystemOneJudgeProvider } from './judge/providers/system-one.ts'\nimport { environmentSecrets } from './judge/redact.ts'\nimport { Config, profileModeOf, resolveConfig } from './runtime/config.ts'\nimport type { DecisionId, ResolvedConfig } from './runtime/config.ts'\nimport { SessionLedgers, ledgerDomain } from './runtime/ledger.ts'\nimport { JEV_BASE_URLS, StoredJevJudge, describeJevKeys, resolveJevKey, storeJevKey } from './runtime/jev.ts'\nimport type { JevKey } from './runtime/jev.ts'\nimport { registerAdmission } from './features/admission.ts'\nimport { registerForgetting } from './features/forgetting.ts'\nimport { registerSkills } from './features/skills.ts'\nimport { HiveRuntime, registerHive } from './features/hive/index.ts'\nimport { hiveView } from './features/hive/view.ts'\nimport { registerMonitor } from './features/monitor/index.ts'\nimport { registerCheckpoint } from './features/checkpoint/index.ts'\nimport type { CheckpointRuntime } from './features/checkpoint/index.ts'\nimport { registerResume } from './features/resume/index.ts'\nimport { registerApproval } from './features/approval/index.ts'\nimport { registerTeam } from './features/team/index.ts'\nimport { SessionRuntime, STATE_KEY } from './runtime/session-state.ts'\nimport { DEFAULT_RECENT_RECORDS, buildStatus } from './runtime/status.ts'\nimport type { JevService, SieveHiveView, SieveJudgeStatus, SieveStatus } from './status.ts'\nimport { registerSieveCommand } from './commands/sieve.ts'\n\nexport * as judge from './judge/index.ts'\nexport { Config, DECISION_IDS, resolveConfig } from './runtime/config.ts'\nexport type { DecisionId, JudgeConfig, JudgeType, ResolvedConfig, ResolvedJudge } from './runtime/config.ts'\nexport { LEDGER_SESSION_CAP, ledgerDomain } from './runtime/ledger.ts'\nexport { DEFAULT_RECENT_RECORDS, MAX_RECENT_RECORDS } from './runtime/status.ts'\nexport { JEV_BASE_URLS, JEV_KEY_REFS, JEV_SERVICES, JevKeyError } from './runtime/jev.ts'\nexport { DSH_TEXT_CHARS_PER_TOKEN } from './status.ts'\nexport type * from './status.ts'\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    sieve: Sieve\n  }\n}\n\n/** One session's view of sieve: the key of its ledger. */\nexport interface SessionScope {\n  readonly sessionId: SessionId\n}\n\n/** How long unloading waits past the judge deadline for calls that ignore their abort. */\nconst SETTLE_MARGIN_MS = 1000\n\n/** Records held while the ledger opens; past this, the oldest are dropped. */\nconst EARLY_RECORD_CAP = 1000\n\nexport class Sieve extends Service {\n  static Config = Config\n\n  readonly config: ResolvedConfig\n  private ledgers: SessionLedgers | undefined\n  /**\n   * Records of decisions made while the ledger was not open: the storage\n   * domain opens asynchronously and the features decide from the first turn.\n   * Written when it opens.\n   */\n  private early: { readonly sessionId: SessionId, record: LedgerRecord }[] = []\n  /** Runtime mode overrides per session; a session without any has no entry. */\n  private readonly overrides = new Map<SessionId, Map<DecisionId, DecisionMode>>()\n  private readonly revisions = new Map<SessionId, number>()\n  private readonly lifetime = new AbortController()\n  /** Every decision and provider call still running, so unloading can wait for them. */\n  private readonly inflight = new Inflight()\n  /** The judge of a `system-one` or `laya` profile; `auto` builds one per call from the stored key. */\n  private readonly configured: JudgeLike | undefined\n  /** Jev keys resolved from the credential store, so judged states never carry them. */\n  private readonly jevSecrets = new Set<string>()\n  /** The hive's bees and runs while the hive is mounted. */\n  hive: HiveRuntime | undefined\n  /** Checkpoints and rewinds while they are mounted. */\n  checkpoints: CheckpointRuntime | undefined\n\n  constructor(ctx: Context, config: Config) {\n    super(ctx, 'sieve')\n    this.config = resolveConfig(config)\n    const live = new Map<SessionId, Set<Agent>>()\n    const remember = (agent: Agent): void => {\n      const id = agent.session.header.id\n      const agents = live.get(id) ?? new Set<Agent>()\n      agents.add(agent)\n      live.set(id, agents)\n    }\n    for (const agent of ctx.get('agents')?.list() ?? []) remember(agent)\n    ctx.on('agent/created', ({ agent }) => { remember(agent); return undefined })\n    ctx.on('agent/disposed', ({ agent }) => {\n      const id = agent.session.header.id\n      const agents = live.get(id)\n      agents?.delete(agent)\n      if (agents === undefined || agents.size === 0) {\n        live.delete(id)\n        this.overrides.delete(id)\n        this.revisions.delete(id)\n      }\n    })\n    const judge = this.config.judge\n    this.configured = judge.type === 'auto'\n      ? undefined\n      : new Judge({\n        provider: judge.type === 'laya'\n          ? new LayaJudgeProvider({ baseUrl: judge.baseUrl })\n          : new SystemOneJudgeProvider({ apiKey: judge.apiKey, baseUrl: judge.baseUrl, model: judge.model }),\n        timeoutMs: judge.timeoutMs,\n        inflight: this.inflight,\n      })\n\n    // Unloading aborts in-flight judge calls (their decisions fall back) and waits for them to stop.\n    // Cordis runs disposers concurrently, so the ledger's disposer below waits for the same calls.\n    ctx.effect(() => () => {\n      this.lifetime.abort(new Error('sieve unloaded'))\n      return this.settle()\n    }, 'sieve.lifetime')\n\n    // The ledger needs the storage domain facility (mounted by dsh-base). Without it\n    // sieve still decides; the latest records wait in memory and are stored once it opens.\n    ctx.plugin({\n      name: 'sieve-ledger',\n      inject: ['storageDomain'],\n      apply: async (child: Context) => {\n        const domain = await child.storageDomain.open(ledgerDomain)\n        const ledgers = new SessionLedgers(domain.table('sessions'), child.logger)\n        this.ledgers = ledgers\n        for (const { sessionId, record } of this.early.splice(0)) void ledgers.append(sessionId, record)\n        child.effect(() => async () => {\n          // Decisions still running record before the ledger closes, whether sieve or only storage unloads.\n          await this.settle()\n          if (this.ledgers === ledgers) this.ledgers = undefined\n          await ledgers.drain()\n          await domain.close()\n        }, 'sieve.ledger')\n      },\n    })\n    ctx.plugin({\n      name: 'sieve-runtime',\n      inject: ['sessionProjections'],\n      apply: (child: Context) => {\n        const runtime = new SessionRuntime(child, agent => this.engineFor(agent))\n        child.plugin({ name: 'sieve-admission', inject: ['tools', 'spillStore'], apply: (feature: Context) => { registerAdmission(feature, this, runtime) } })\n        child.plugin({ name: 'sieve-forgetting', inject: ['spillStore'], apply: (feature: Context) => { registerForgetting(feature, this, runtime) } })\n        child.plugin({ name: 'sieve-skills', inject: ['skills'], apply: (feature: Context) => { registerSkills(feature, this, runtime) } })\n        if (this.config.monitor.enabled) {\n          child.plugin({ name: 'sieve-monitor', inject: ['tools'], apply: (feature: Context) => { registerMonitor(feature, this, runtime) } })\n        }\n        if (this.config.checkpoint.enabled) {\n          child.plugin({\n            name: 'sieve-checkpoint',\n            inject: ['tools'],\n            apply: (feature: Context) => {\n              const checkpoints = registerCheckpoint(feature, this, runtime)\n              this.checkpoints = checkpoints\n              feature.effect(() => () => {\n                if (this.checkpoints === checkpoints) this.checkpoints = undefined\n              }, 'sieve.checkpoint-runtime')\n            },\n          })\n        }\n        if (this.config.resume.enabled) {\n          child.plugin({ name: 'sieve-resume', apply: (feature: Context) => { registerResume(feature, this, runtime) } })\n        }\n        if (this.config.approval.enabled) {\n          child.plugin({\n            name: 'sieve-approval',\n            inject: ['permissionPresets', 'approval', 'sessions', 'agents'],\n            apply: (feature: Context) => { registerApproval(feature, this, runtime) },\n          })\n        }\n        // Only where DSH's agent team is mounted: without it the plugin waits for a service that never comes.\n        if (this.config.team.enabled) {\n          child.plugin({\n            name: 'sieve-team',\n            inject: ['agentTeams', 'subagents', 'agents', 'tools'],\n            apply: (feature: Context) => { registerTeam(feature, this, runtime) },\n          })\n        }\n      },\n    })\n    if (this.config.hive.enabled) {\n      ctx.plugin({\n        name: 'sieve-hive',\n        inject: ['subagents', 'tools', 'agents'],\n        apply: (child: Context) => {\n          const runtime = new HiveRuntime()\n          this.hive = runtime\n          child.effect(() => () => {\n            if (this.hive === runtime) this.hive = undefined\n          }, 'sieve.hive-runtime')\n          registerHive(child, this, runtime)\n        },\n      })\n    }\n    ctx.plugin({\n      name: 'sieve-command',\n      inject: ['commands'],\n      apply: (child: Context) => { registerSieveCommand(child, this) },\n    })\n  }\n\n  /**\n   * The mode a decision runs in: the session's runtime override, else the\n   * profile's (`profileModeOf`). Without a session, the profile's.\n   */\n  modeOf(specId: string, sessionId?: SessionId): DecisionMode {\n    const id = specId as DecisionId\n    const override = sessionId === undefined ? undefined : this.overrides.get(sessionId)?.get(id)\n    return override ?? profileModeOf(this.config, id)\n  }\n\n  /** Override a decision's mode in one session until the service unloads; undefined returns it to the profile. */\n  setMode(sessionId: SessionId, specId: DecisionId, mode: DecisionMode | undefined): void {\n    this.revisions.set(sessionId, this.revisionOf(sessionId) + 1)\n    const session = this.overrides.get(sessionId)\n    if (mode !== undefined) {\n      if (session === undefined) this.overrides.set(sessionId, new Map([[specId, mode]]))\n      else session.set(specId, mode)\n      return\n    }\n    session?.delete(specId)\n    if (session?.size === 0) this.overrides.delete(sessionId)\n  }\n\n  revisionOf(sessionId: SessionId): number {\n    return this.revisions.get(sessionId) ?? 0\n  }\n\n  /**\n   * Whether a judge model is configured: Jev or Laya in the profile, or, for\n   * `auto`, a Jev key in the credential store now. Without one sieve changes\n   * nothing, rules included; the session model never stands in.\n   */\n  async judgeReady(): Promise<boolean> {\n    return this.config.judge.type !== 'auto' || await this.resolveJev() !== undefined\n  }\n\n  track<T>(work: Promise<T>): Promise<T> {\n    return this.inflight.track(work)\n  }\n\n  /** Whether the ledger is mounted. */\n  get recording(): boolean {\n    return this.ledgers !== undefined\n  }\n\n  /**\n   * One session's state as JSON: modes, ledger totals and its latest\n   * records. Without a live agent the log marker count is unknown, and no\n   * override can exist.\n   */\n  status(sessionId: SessionId, options: { readonly recent?: number } = {}): SieveStatus {\n    const agent = this.ctx.get('agents')?.get(sessionId)\n    const reducedResults = agent === undefined\n      ? null\n      : this.ctx.get('sessionProjections')?.stateOf(agent.session, STATE_KEY)?.reduced ?? 0\n    return buildStatus({\n      sessionId,\n      live: agent !== undefined,\n      config: this.config,\n      recording: this.recording,\n      records: this.ledger(sessionId),\n      reducedResults,\n      contextTokens: agent === undefined ? null : this.contextTokens(agent),\n      modeOf: id => this.modeOf(id, sessionId),\n      overridden: id => this.overrides.get(sessionId)?.has(id) ?? false,\n      recent: options.recent ?? DEFAULT_RECENT_RECORDS,\n      checkpoint: this.checkpoints?.status(sessionId, agent),\n    })\n  }\n\n  /** A session's hives for the Web panel: the stored runs and the running ones as they are now. */\n  hiveView(sessionId: SessionId): SieveHiveView {\n    return hiveView(this.config.hive.enabled, this.hive?.records(sessionId) ?? [])\n  }\n\n  /** Which judge answers next, and which Jev keys the credential store holds (never their values). */\n  async judgeStatus(): Promise<SieveJudgeStatus> {\n    const judge = this.config.judge\n    const keys = await describeJevKeys(this.ctx.get('credentials'))\n    const stored = keys.find(key => key.configured)\n    const using: SieveJudgeStatus['using'] = judge.type === 'laya'\n      ? { kind: 'laya' }\n      : judge.type === 'system-one'\n        ? { kind: 'jev', service: judge.baseUrl === undefined ? 'typesafe' : judge.baseUrl === JEV_BASE_URLS.openrouter ? 'openrouter' : null }\n        : stored !== undefined ? { kind: 'jev', service: stored.service } : { kind: 'none' }\n    return { type: judge.type, using, keys }\n  }\n\n  /**\n   * Store one service's Jev key in DSH's credential store, or remove it with\n   * `undefined`. An `auto` judge reads it from the next call on.\n   * @throws {JevKeyError} without a credential store, or for a key the process environment supplies.\n   */\n  async setJevKey(service: JevService, apiKey: string | undefined): Promise<void> {\n    await storeJevKey(this.ctx.get('credentials'), service, apiKey)\n    if (apiKey !== undefined) this.jevSecrets.add(apiKey)\n  }\n\n  /** A session's ledger records, oldest first; the held ones while the ledger is not open. */\n  ledger(sessionId: SessionId): readonly LedgerRecord[] {\n    return this.ledgers?.records(sessionId) ?? this.early.filter(entry => entry.sessionId === sessionId).map(entry => entry.record)\n  }\n\n  /**\n   * Add what the host learned after a record was written; nothing when the\n   * ledger is not mounted. Never rejects: a failed write is logged by the ledger.\n   */\n  async annotate(sessionId: SessionId, ledgerId: string, patch: LedgerAnnotation): Promise<void> {\n    if (this.ledgers !== undefined) return this.ledgers.annotate(sessionId, ledgerId, patch)\n    const entry = this.early.find(each => each.sessionId === sessionId && each.record.id === ledgerId)\n    if (entry !== undefined) entry.record = { ...entry.record, ...patch }\n  }\n\n  private append(sessionId: SessionId, record: LedgerRecord): Promise<void> | undefined {\n    if (this.ledgers !== undefined) return this.ledgers.append(sessionId, record)\n    this.early.push({ sessionId, record })\n    if (this.early.length > EARLY_RECORD_CAP) this.early.shift()\n    return undefined\n  }\n\n  /** A decision engine for one session: the configured judge, the current modes, the session's ledger. */\n  engine(scope: SessionScope): DecisionEngine {\n    return new DecisionEngine({\n      judge: () => this.judgeFor(),\n      mode: specId => this.modeOf(specId, scope.sessionId),\n      ledger: { append: record => this.append(scope.sessionId, record) },\n      recordState: this.config.recordState,\n      knownSecrets: () => this.knownSecrets(),\n      signal: this.lifetime.signal,\n      inflight: this.inflight,\n    })\n  }\n\n  /** The same for an agent: its session's ledger. */\n  engineFor(agent: Agent): DecisionEngine {\n    return this.engine({ sessionId: agent.session.header.id })\n  }\n\n  private judgeFor(): JudgeLike {\n    const judge = this.config.judge\n    if (this.configured !== undefined) return this.configured\n    return new StoredJevJudge({\n      resolve: () => this.resolveJev(),\n      jev: key => new Judge({\n        provider: new SystemOneJudgeProvider({ apiKey: key.apiKey, baseUrl: JEV_BASE_URLS[key.service] }),\n        timeoutMs: judge.timeoutMs,\n        inflight: this.inflight,\n      }),\n    })\n  }\n\n  /** The stored Jev key for this call, if any; remembered for redaction. */\n  private async resolveJev(): Promise<JevKey | undefined> {\n    const key = await resolveJevKey(this.ctx.get('credentials'))\n    if (key !== undefined) this.jevSecrets.add(key.apiKey)\n    return key\n  }\n\n  /** Route-priced tokens of the agent's current request surface; null when it cannot be measured. */\n  private contextTokens(agent: Agent): number | null {\n    const meter = this.ctx.get('tokenMeter')\n    if (meter === undefined) return null\n    try {\n      return meter.measure(agent.session).surfaceTokens\n    } catch {\n      // A status read must not fail because the session is mid-replay.\n      return null\n    }\n  }\n\n  /** Waits for running decisions and provider calls, bounded by the judge deadline plus a margin. */\n  private async settle(): Promise<void> {\n    const judge = this.config.judge\n    const bound = judge.timeoutMs + SETTLE_MARGIN_MS\n    if (await this.inflight.settle(bound)) return\n    this.ctx.logger.warn(`sieve: ${this.inflight.size} judge call(s) still running ${bound} ms after unload began; no longer waiting`)\n  }\n\n  private knownSecrets(): readonly string[] {\n    const judge = this.config.judge\n    const secrets = [...environmentSecrets(), ...this.jevSecrets]\n    return judge.type === 'system-one' ? [judge.apiKey, ...secrets] : secrets\n  }\n}\n\nexport default Sieve\n"
    },
    {
      "path": "packages/dsh-sieve/src/features/admission.ts",
      "content": "/** DSH post-execute admission: bounded judgments, durable originals, content-only replacements. */\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport type { SpillRef } from '@deepseek-ai/dsh-spill'\nimport type { PostToolDecision, ToolExecution } from '@deepseek-ai/dsh-tools'\nimport { isTestLog, planTestLog, renderTestLogBody, testLogSelection } from '../judge/admission/test-log.ts'\nimport { toolAdmissionBatch } from '../judge/decisions/tool-admission.ts'\nimport type { AdmissionOutcome } from '../judge/decisions/tool-admission.ts'\nimport type { Decision, DecisionEngine } from '../judge/engine.ts'\nimport type { LedgerAnnotation, LedgerRecord } from '../judge/ledger.ts'\nimport type { ResolvedConfig } from '../runtime/config.ts'\nimport { deadline, untilAbort } from '../runtime/operations.ts'\nimport { isSieveResult, SessionRuntime, textOf } from '../runtime/session-state.ts'\nimport type { AdmissionRewrite } from '../runtime/session-state.ts'\nimport { chunkLines, dedupAgainst, describeCall, foldSimilarLines, FULL_OUTPUT_REQUEST, judgeCandidates } from './admission-rules.ts'\nimport type { RuleResult, VisibleOutput } from './admission-rules.ts'\nimport { FORGET_STATE_KEY } from './forgetting.ts'\n\nexport interface AdmissionHost {\n  readonly config: ResolvedConfig\n  engineFor(agent: Agent): DecisionEngine\n  annotate(sessionId: SessionId, ledgerId: string, patch: LedgerAnnotation): Promise<void>\n  /** A session's ledger records, oldest first. */\n  ledger(sessionId: SessionId): readonly LedgerRecord[]\n  track<T>(work: Promise<T>): Promise<T>\n  revisionOf(sessionId: SessionId): number\n  /** Whether a judge model (Jev or Laya) is configured; without one no decision changes anything. */\n  judgeReady(): Promise<boolean>\n}\n\n/**\n * Stands in for the archive pointer when a saving is estimated, so shadow,\n * where nothing is archived, and active estimate alike.\n */\nconst ESTIMATE_LOCATOR = '<archive>'\n/** Chunks of one output asked about in one judge request. */\nconst CHUNKS_PER_REQUEST = 16\n\nfunction parseArguments(text: string): unknown {\n  try { return JSON.parse(text) } catch { return text }\n}\n\n/** The body followed by the one pointer to the archived original, and the retrieval hint. */\nfunction withPointer(body: string, locator: string, hint: string): string {\n  return `${body}${body.endsWith('\\n') ? '' : '\\n'}[sieve: full output: ${locator}]\\n${hint === '' ? '' : `${hint}\\n`}`\n}\n\nexport function registerAdmission(ctx: Context, host: AdmissionHost, runtime: SessionRuntime): void {\n  const receipts = new WeakMap<ToolExecution, AdmissionRewrite>()\n  const config = host.config.admission\n  const sources = new WeakMap<object, readonly VisibleOutput[]>()\n\n  ctx.on('tools/result', (exec, result) => {\n    const receipt = receipts.get(exec)\n    if (receipt === undefined) return\n    receipts.delete(exec)\n    // An outer finalizer may have replaced the rewrite; then nothing of it reached the model.\n    const survived = !result.isError && textOf(result.content) === receipt.replacement\n    for (const { id, changed } of receipt.records) void host.track(host.annotate(receipt.sessionId, id, { applied: changed && survived }))\n  })\n\n  /** Earlier results the model still sees. The forgetting projection keeps them, minus whatever was replaced since. */\n  const visibleOutputs = (agent: Agent): readonly VisibleOutput[] => {\n    const state = ctx.sessionProjections.stateOf(agent.session, FORGET_STATE_KEY)\n    if (state === undefined) return []\n    const cached = sources.get(state.candidates)\n    if (cached !== undefined) return cached\n    const outputs = state.candidates.map(candidate => ({\n      callId: candidate.data.message.toolCallId,\n      label: candidate.call === null ? 'tool' : describeCall(candidate.call.name, parseArguments(candidate.call.arguments)),\n      text: textOf(candidate.data.message.content),\n    }))\n    sources.set(state.candidates, outputs)\n    return outputs\n  }\n\n  const transform = async (exec: ToolExecution, agent: Agent, original: string): Promise<AdmissionRewrite | undefined> => {\n    const state = runtime.for(agent)\n    const task = runtime.task(agent)\n    if (task === undefined) return undefined\n    const sessionId = agent.session.header.id\n    const revision = task.revision\n    const settingsRevision = host.revisionOf(sessionId)\n    const origin = { callId: exec.callId, rootCallId: exec.rootCallId, toolName: exec.name, userMessageId: task.userMessageId, nested: exec.parent !== undefined }\n    const goal = [...new Set([task.firstUser, task.lastUser].filter(Boolean))].join('\\n')\n    const intent = task.lastAssistant.slice(0, 400)\n    if (FULL_OUTPUT_REQUEST.test(`${task.lastUser}\\n${intent}`)) return undefined\n\n    const engine = state.engine\n    const args = typeof exec.arguments === 'object' && exec.arguments !== null ? exec.arguments as Record<string, unknown> : {}\n    const command = exec.name === 'bash' && typeof args['command'] === 'string' ? args['command'] : undefined\n    // File content gets only the lossless reference to text the model already has.\n    const content = config.contentTools.includes(exec.name)\n    const testLog = !content && command !== undefined && config.testLog !== 'off' && isTestLog(`bash: ${command}`, original)\n    // The mode governs the rules as much as the judge: off leaves the output alone, shadow only measures.\n    const mode = engine.modeOf(testLog ? testLogSelection.id : toolAdmissionBatch.id)\n    if (mode === 'off' || !await host.judgeReady()) return undefined\n\n    /** A replacement must save at least this much, after its markers and pointer. */\n    const floor = Math.max(config.minNetChars, original.length * config.minNetShare)\n    const saved = (text: string): number => original.length - text.length\n    // A nested PTC call's content goes to a program, which cannot follow a reference to the model's context.\n    const outputs = config.dedup && exec.parent === undefined ? visibleOutputs(agent) : undefined\n    // Numbered file lines never repeat inside one read, and file content is not referenced to itself.\n    const dedup = (text: string): RuleResult => outputs === undefined ? { text, lines: 0 } : dedupAgainst(text, outputs, { self: !content })\n    /** What the model sees for a body: the original when nothing changed or too little is saved. */\n    const finish = (body: string, locator: string, hint: string): string => {\n      if (body === original) return original\n      const text = withPointer(body, locator, hint)\n      return saved(text) >= floor ? text : original\n    }\n    // Cancellation, a new user request or a settings change void the work; the deadline only ends the wait.\n    const cancel = AbortSignal.any([exec.signal, state.controller.signal])\n    const valid = (): boolean => !cancel.aborted && runtime.task(agent)?.revision === revision && host.revisionOf(sessionId) === settingsRevision\n    const bound = deadline(cancel, config.waitMs)\n    const wait = bound.signal\n    let archived: SpillRef | undefined\n    const archive = (): Promise<SpillRef> => {\n      const saving = host.track(ctx.spillStore.saveText({\n        owner: { sessionId }, source: { kind: 'tool', toolName: exec.name, callId: exec.callId, label: 'sieve-original' },\n        suggestedName: `${exec.name}-original.txt`, content: original,\n      }))\n      saving.then(ref => { archived = ref }, () => {})\n      return saving\n    }\n    const annotate = (id: string, patch: LedgerAnnotation): void => {\n      void host.track(host.annotate(sessionId, id, patch))\n    }\n\n    try {\n      if (testLog) {\n        const input = { call: `bash: ${command}`, goal, intent, output: original }\n        // The rules need no judge; their plan is the baseline every other outcome builds on.\n        const rules = await planTestLog(input, 'rules', engine, { origin })\n        const bodyOf = (omitted: readonly string[]): RuleResult => {\n          const folded = renderTestLogBody({ ...rules, omitted })\n          const repeated = dedup(folded.text)\n          return { text: repeated.text, lines: folded.omittedLines + repeated.lines }\n        }\n        const baseline = rules.omitted\n        const rulesBody = bodyOf(baseline)\n        const rulesSaved = saved(finish(rulesBody.text, ESTIMATE_LOCATOR, ''))\n        const rulesId = rulesBody.text === original ? undefined : engine.recordRules(testLogSelection, {\n          outcome: { omit: [...baseline], lines: rulesBody.lines },\n          state: { call: input.call, units: rules.units.map(unit => ({ id: unit.id, kind: unit.kind, lines: unit.lines })) },\n          origin, savedChars: rulesSaved, applied: false,\n        })\n        const judgeSaved = (judged: readonly string[] | undefined): number =>\n          judged === undefined ? 0 : Math.max(0, saved(finish(bodyOf(judged).text, ESTIMATE_LOCATOR, '')) - rulesSaved)\n        const judging = config.testLog !== 'judge' ? undefined : host.track(planTestLog(input, 'judge', engine, {\n          // Shadow is never waited for, so only cancellation bounds it; the judge keeps its own deadline.\n          signal: mode === 'shadow' ? cancel : wait, origin,\n        }))\n        let judgeId: string | undefined\n        // Registered before anything waits on the plan, so its annotation is queued ahead of the applied flag.\n        void judging?.then(plan => {\n          if (plan.ledgerId === undefined) return\n          judgeId = plan.ledgerId\n          annotate(plan.ledgerId, { applied: false, savedChars: judgeSaved(plan.judged) })\n        }).catch(() => {})\n        if (mode === 'shadow') return undefined\n\n        // Whatever the judge does, the rules result stands: archive for it while the judge thinks.\n        const early = rulesSaved > 0 ? archive() : undefined\n        let omitted = baseline\n        if (judging !== undefined) {\n          const plan = await untilAbort(judging, wait)\n          // Late, failed or aborted: the rules result.\n          if (plan !== undefined) omitted = plan.omitted\n        }\n        const body = bodyOf(omitted).text\n        if (!valid() || finish(body, ESTIMATE_LOCATOR, '') === original) return undefined\n        const ref = archived ?? await untilAbort(early ?? archive(), wait)\n        if (ref === undefined || !valid()) return undefined\n        const replacement = finish(body, ref.locator, ref.retrievalHint)\n        if (replacement === original) return undefined\n        const records: { id: string, changed: boolean }[] = []\n        if (rulesId !== undefined) records.push({ id: rulesId, changed: true })\n        if (judgeId !== undefined) records.push({ id: judgeId, changed: replacement !== finish(rulesBody.text, ref.locator, ref.retrievalHint) })\n        return { sessionId, replacement, records }\n      }\n\n      // The rules: similar lines fold (never in file content), then repeats of what the model already has.\n      const call = describeCall(exec.name, exec.arguments)\n      const folded = content || !config.foldSimilar ? { text: original, lines: 0 } : foldSimilarLines(original, goal, intent)\n      const repeated = dedup(folded.text)\n      const rulesBody = repeated.text\n      const rulesSaved = saved(finish(rulesBody, ESTIMATE_LOCATOR, ''))\n      const rulesId = rulesBody === original ? undefined : engine.recordRules(toolAdmissionBatch, {\n        outcome: { folded: folded.lines, repeated: repeated.lines },\n        state: { call },\n        origin, savedChars: rulesSaved, applied: false,\n      })\n\n      // The judge: middle chunks of a long output that is not file content, on top of the rules.\n      const chunks = chunkLines(rulesBody, config.chunkChars)\n      const indexes = content || rulesBody.length < config.judgeMinChars || chunks.length < 3 || chunks.length > config.maxChun