    {
      "path": "packages/dsh-sieve/src/features/forgetting.ts",
      "content": "/**\n * Batched, log-backed forgetting.\n * Contains MIT-licensed third-party code, see THIRD_PARTY_NOTICES.md.\n *\n * Results of the most recent steps stay whole. Older command output, and\n * reads that a later read of the same lines superseded, are archived and\n * replaced by their ends and a pointer; the judge may add results inside the\n * recent window that the work has moved past. An older file read is the\n * judge's call, not the rules': a task that studies several files steps away\n * from them and comes back. A file read again after it was forgotten is not\n * forgotten by age again, and the re-read is charged against the saving.\n * Replacing a result breaks the cached prefix from there on, so replacements\n * wait until one batch saves `minBatchChars`, and a batch lands before one\n * request. There are no 50/70/85% context-window thresholds: on public SWE\n * trajectories most tasks never reach them, while a batch of old results pays\n * for its cache rebuild within a few requests.\n */\nimport { resolve } from 'node:path'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type {} from '@deepseek-ai/dsh-compaction'\nimport { freezeMessage } from '@deepseek-ai/dsh-llm'\nimport { SessionSeq } from '@deepseek-ai/dsh-session'\nimport type { SessionEvent, ToolResultMessage } from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-working-directory'\nimport { estimateMessage } from '@deepseek-ai/dsh-token-meter/estimate'\nimport { z } from 'zod'\nimport { contextForget } from '../judge/decisions/context-forget.ts'\nimport type { Decision } from '../judge/engine.ts'\nimport type { ForgetOutcome } from '../judge/decisions/context-forget.ts'\nimport { deadline, untilAbort } from '../runtime/operations.ts'\nimport { textOf } from '../runtime/session-state.ts'\nimport type { SessionRuntime } from '../runtime/session-state.ts'\nimport type { AdmissionHost } from './admission.ts'\nimport { FULL_OUTPUT_REQUEST, referencedCalls } from './admission-rules.ts'\n\nexport const FORGET_STATE_KEY = 'sieve/forgetting'\n/** The pointer line of a forgotten result; `at N%` is the marker version 1 wrote. */\nconst FORGOTTEN = /^\\[sieve: forgotten(?: at [\\d,]+%|, superseded by a later read)?; full output: [^\\]\\r\\n]+\\]\\r?$/m\nconst SUPERSEDED = /^\\[sieve: forgotten, superseded by a later read; full output: /m\n/** Shorter results are not tracked: forgetting them would save nothing. */\nconst MIN_TRACKED_CHARS = 300\n/** The judge is asked about results inside the recent window at least this many steps old. */\nconst JUDGE_MIN_AGE = 2\nconst PREVIEW_CHARS = 300\n\ninterface Call {\n  id: string\n  name: string\n  arguments: string\n  /** The session's working directory when the call was made; null is the original project. */\n  cwd: string | null\n}\n\nexport interface ForgetCandidate {\n  seq: number\n  data: SessionEvent<'tool/result'>['data']\n  call: Call | null\n  /** This result's number among the session's tool results; each later result makes it one older. */\n  ordinal: number\n  /** The step the result arrived in, counted from the session's first; its age is in steps. */\n  step: number\n  chars: number\n}\n\n/** A file read that forgetting replaced by its ends; reading the file again shows the forgetting was early. */\nexport interface ForgottenRead {\n  /** Sequence of the read that was forgotten. */\n  seq: number\n  /** Sequence of the replacement; only a read after it is a re-read. */\n  at: number\n  /** `file_path` as the read asked for it; resolved against `cwd` when compared. */\n  path: string\n  /** The working directory of the forgotten read; null is the original project. */\n  cwd: string | null\n  /** Characters the replacement removed. */\n  saved: number\n}\n\n/** A visible result that refers to earlier outputs instead of repeating them. */\nexport interface Reference {\n  seq: number\n  calls: string[]\n}\n\nexport interface ForgetState {\n  candidates: ForgetCandidate[]\n  /** While a reference is visible, the output it points to is not forgotten. */\n  references: Reference[]\n  calls: Call[]\n  /** Tool results seen, replacements not counted. */\n  results: number\n  /** Steps started in the session. */\n  steps: number\n  forgottenReads: ForgottenRead[]\n  epoch: number\n  since: string[]\n  forgotten: number\n  /** The latest `working-directory/change`; null until the session leaves its original project. */\n  cwd: string | null\n}\n\ndeclare module '@deepseek-ai/dsh-session-projection/types' {\n  interface SessionProjectionStateMap {\n    'sieve/forgetting': ForgetState\n  }\n}\n\nexport interface ReadRange {\n  /** The resolved path. */\n  readonly identity: string\n  readonly first: number\n  readonly last: number\n}\n\n/** The `file_path` a read call asked for; undefined for other calls. */\nexport function readPath(call: Call | null): string | undefined {\n  if (call?.name !== 'read') return undefined\n  try {\n    const args: unknown = JSON.parse(call.arguments)\n    if (typeof args !== 'object' || args === null || Array.isArray(args)) return undefined\n    const path = (args as Record<string, unknown>)['file_path']\n    return typeof path === 'string' && path !== '' ? path : undefined\n  } catch { return undefined }\n}\n\nconst READ_FOOTER = /\\n\\n\\((?:End of file - total \\d+ lines|Showing lines \\d+-\\d+ of \\d+\\. Use offset=\\d+ to continue\\.|Output capped\\. Showing lines \\d+-\\d+\\. Use offset=\\d+ to continue\\.)\\)$/\n\n/**\n * The file and the line range a DSH read showed, from its arguments and its\n * envelope. Undefined for anything else, and for a read whose numbered lines\n * do not run without a gap, such as one admission already shortened.\n */\nexport function readRange(candidate: ForgetCandidate, cwd: string): ReadRange | undefined {\n  if (candidate.call?.name !== 'read' || candidate.data.message.isError) return undefined\n  let args: unknown\n  try { args = JSON.parse(candidate.call.arguments) } catch { return undefined }\n  if (typeof args !== 'object' || args === null || Array.isArray(args)) return undefined\n  const input = args as Record<string, unknown>\n  if (typeof input['file_path'] !== 'string' || Object.keys(input).some(key => !['file_path', 'offset', 'limit'].includes(key))) return undefined\n  const text = textOf(candidate.data.message.content)\n  const match = /^<path>([^\\n]+)<\\/path>\\n<type>file<\\/type>\\n<content>\\n([\\s\\S]*)\\n<\\/content>$/.exec(text)\n  if (match === null || resolve(cwd, match[1] ?? '') !== resolve(cwd, input['file_path'])) return undefined\n  const body = match[2] ?? ''\n  const footer = READ_FOOTER.exec(body)\n  if (footer === null) return undefined\n  const lines = body.slice(0, footer.index).split('\\n')\n  const numbers = lines.map(line => /^(\\d+): /.exec(line)?.[1])\n  const first = Number(numbers[0])\n  if (numbers.some((value, index) => value === undefined || Number(value) !== first + index)) return undefined\n  return { identity: resolve(cwd, input['file_path']), first, last: first + numbers.length - 1 }\n}\n\nfunction folded(state: ForgetState, event: SessionEvent, cap: number, budget: number): ForgetState {\n  const op = event.surfaceOp\n  const replaced = typeof op !== 'object' ? [] : state.candidates.filter(candidate => candidate.seq >= op.startSeq && candidate.seq <= op.endSeq)\n  if (replaced.length > 0) state = { ...state, candidates: state.candidates.filter(candidate => !replaced.includes(candidate)) }\n  if (typeof op === 'object' && state.references.some(reference => reference.seq >= op.startSeq && reference.seq <= op.endSeq)) {\n    state = { ...state, references: state.references.filter(reference => reference.seq < op.startSeq || reference.seq > op.endSeq) }\n  }\n  if (event.type === 'assistant/message') {\n    const text = textOf(event.data.message.content).replace(/\\s+/g, ' ').slice(0, 160)\n    return text === '' ? state : { ...state, since: [...state.since, text].slice(-4) }\n  }\n  if (event.type === 'working-directory/change') return { ...state, cwd: event.data.cwd }\n  if (event.type === 'tool/call') {\n    const { callId, name, arguments: args } = event.data\n    return { ...state, calls: [...state.calls, { id: callId, name, arguments: args.length <= 8000 ? args : '', cwd: state.cwd }].slice(-cap) }\n  }\n  if (event.type === 'step/start') return { ...state, steps: state.steps + 1 }\n  if (event.type === 'compaction/end' && event.data.error === undefined) return { ...state, epoch: event.seq }\n  if (event.type !== 'tool/result') return state\n  const callId = event.data.message.toolCallId\n  // A replacement (a pruner's, sieve's own) stands where the result it replaces stood.\n  const before = replaced.find(candidate => candidate.data.message.toolCallId === callId)\n  const call = state.calls.find(item => item.id === callId) ?? before?.call ?? null\n  const calls = state.calls.filter(item => item.id !== callId)\n  const results = typeof op === 'object' ? state.results : state.results + 1\n  const text = textOf(event.data.message.content)\n  if (FORGOTTEN.test(text)) {\n    // A superseded read keeps a later copy in view; only a read forgotten by age or judge can come back.\n    const path = before === undefined || SUPERSEDED.test(text) ? undefined : readPath(before.call)\n    const forgottenReads = before === undefined || path === undefined ? state.forgottenReads\n      : [...state.forgottenReads, { seq: before.seq, at: event.seq, path, cwd: before.call?.cwd ?? null, saved: Math.max(0, before.chars - text.length) }].slice(-cap)\n    return { ...state, calls, results, forgotten: state.forgotten + 1, forgottenReads }\n  }\n  const pointed = referencedCalls(text)\n  if (pointed.length > 0) state = { ...state, references: [...state.references, { seq: event.seq, calls: pointed }].slice(-cap) }\n  if (event.data.message.isError || event.data.message.content.some(block => block.type !== 'text') || text.length < MIN_TRACKED_CHARS || text.length > budget) {\n    return { ...state, calls, results }\n  }\n  const ordinal = before?.ordinal ?? results\n  const step = before?.step ?? state.steps\n  const retained = [...state.candidates, { seq: event.seq, data: event.data, call, ordinal, step, chars: text.length }].slice(-cap)\n  let total = retained.reduce((sum, candidate) => sum + candidate.chars, 0)\n  while (total > budget && retained.length > 0) total -= retained.shift()?.chars ?? 0\n  return { ...state, calls, results, candidates: retained }\n}\n\n/** A result's start and end around the pointer; a superseded read keeps only the pointer. */\nfunction replacement(candidate: ForgetCandidate, superseded: boolean, edge: number, locator: string, hint = ''): string {\n  const pointer = `[sieve: forgotten${superseded ? ', superseded by a later read' : ''}; full output: ${locator}]\\n${hint === '' ? '' : `${hint}\\n`}`\n  if (superseded) return pointer\n  // By code point, so surrogate pairs cannot split.\n  const points = Array.from(textOf(candidate.data.message.content))\n  return `${points.slice(0, edge).join('')}\\n${pointer}${edge === 0 ? '' : points.slice(-edge).join('')}`\n}\n\nfunction preview(candidate: ForgetCandidate): string {\n  const points = Array.from(textOf(candidate.data.message.content))\n  if (points.length <= 2 * PREVIEW_CHARS) return points.join('')\n  return `${points.slice(0, PREVIEW_CHARS).join('')}\\n[${points.length - 2 * PREVIEW_CHARS} characters not shown]\\n${points.slice(-PREVIEW_CHARS).join('')}`\n}\n\nexport function registerForgetting(ctx: Context, host: AdmissionHost, runtime: SessionRuntime): void {\n  const config = host.config.forgetting\n  ctx.sessionProjections.register({\n    key: FORGET_STATE_KEY, stateVersion: 4,\n    stateSchema: z.custom<ForgetState>(value => typeof value === 'object' && value !== null && 'candidates' in value && 'references' in value),\n    init: () => ({ candidates: [], references: [], calls: [], results: 0, steps: 0, forgottenReads: [], epoch: -1, since: [], forgotten: 0, cwd: null }),\n    apply: (state, event) => folded(state, event, config.maxTrackedResults, config.maxStateChars),\n  })\n  /**\n   * Results already forgotten by rule, or asked about, in this epoch: shadow\n   * records each once, and a failed archive is not retried every step. A\n   * command result the judge kept still ages into the rules; a file read the\n   * judge kept is asked again once its age has doubled.\n   */\n  const batched = new WeakMap<Agent, { epoch: number, settings: number, ruled: Set<number>, asked: Map<number, number> }>()\n  /** Forgotten reads whose re-read is already charged, by the forgotten read's seq. */\n  const charged = new WeakMap<Agent, Set<number>>()\n  ctx.on('agent/pre-step', async ({ agent, messages, signal }, next) => {\n    const run = async (): Promise<void> => {\n      // Checked first: the projection read below must not go stale across the await.\n      if (!await host.judgeReady()) return\n      const state = ctx.sessionProjections.stateOf(agent.session, FORGET_STATE_KEY)\n      const task = runtime.task(agent)\n      const agentState = runtime.for(agent)\n      const mode = agentState.engine.modeOf(contextForget.id)\n      if (!config.enabled || mode === 'off' || state === undefined || task === undefined) return\n      const sessionId = agent.session.header.id\n      const onSurface = (seq: number): boolean => agent.session.surface.nodes.includes(SessionSeq(seq))\n      // A read resolves against the directory it ran in; the session can change it between calls.\n      const cwdOf = (cwd: string | null | undefined): string => cwd ?? agent.session.header.cwd ?? '.'\n      // The latest forgetting of each file; a visible read of it after that is a re-read.\n      const forgottenAt = new Map(state.forgottenReads.map(entry => [resolve(cwdOf(entry.cwd), entry.path), entry]))\n      const rereadOf = (candidate: ForgetCandidate): ForgottenRead | undefined => {\n        const path = readPath(candidate.call)\n        const entry = path === undefined ? undefined : forgottenAt.get(resolve(cwdOf(candidate.call?.cwd), path))\n        return entry !== undefined && entry.at < candidate.seq ? entry : undefined\n      }\n      chargeRereads(agent, state.candidates.filter(candidate => onSurface(candidate.seq)), rereadOf)\n\n      const request = [...messages].reverse().find(message => message.source.kind === 'user')\n      const current = request === undefined ? task.lastUser : textOf(request.content)\n      if (current.trim() === '' || FULL_OUTPUT_REQUEST.test(`${current}\\n${request === undefined ? task.lastAssistant : ''}`)) return\n      const cancel = AbortSignal.any([signal, agentState.controller.signal])\n      const revision = task.revision\n      const settings = host.revisionOf(sessionId)\n      const epoch = state.epoch\n      const valid = (): boolean => !cancel.aborted && runtime.task(agent)?.revision === revision\n        && host.revisionOf(sessionId) === settings && ctx.sessionProjections.stateOf(agent.session, FORGET_STATE_KEY)?.epoch === epoch\n      let done = batched.get(agent)\n      if (done === undefined || done.epoch !== epoch || done.settings !== settings) {\n        done = { epoch, settings, ruled: new Set(), asked: new Map() }\n        batched.set(agent, done)\n      }\n      const { ruled, asked: judgedBefore } = done\n\n      // A visible reference points into its source: forgetting the source would lose what the reference stands for.\n      const referenced = new Set(state.references.filter(reference => onSurface(reference.seq)).flatMap(reference => reference.calls))\n      const visible = state.candidates.filter(candidate => onSurface(candidate.seq) && !referenced.has(candidate.data.message.toolCallId))\n      const age = (candidate: ForgetCandidate): number => state.steps - candidate.step\n      const isRead = (candidate: ForgetCandidate): boolean => candidate.call?.name === 'read'\n      const ranges = new Map(visible.map(candidate => [candidate.seq, readRange(candidate, cwdOf(candidate.call?.cwd))]))\n      const superseded = new Set(visible.filter((candidate, index) => {\n        const range = ranges.get(candidate.seq)\n        return range !== undefined && visible.slice(index + 1).some(later => {\n          const cover = ranges.get(later.seq)\n          return cover?.identity === range.identity && cover.first <= range.first && cover.last >= range.last\n        })\n      }).map(candidate => candidate.seq))\n      const estimate = (candidate: ForgetCandidate): number =>\n        Math.max(0, candidate.chars - replacement(candidate, superseded.has(candidate.seq), config.edgeChars, '<archive>').length)\n      const sum = (candidates: readonly ForgetCandidate[]): number => candidates.reduce((total, candidate) => total + estimate(candidate), 0)\n      const aged = (candidate: ForgetCandidate): boolean => age(candidate) >= config.keepRecent && candidate.chars >= config.minChars\n      // Only a later copy of the same lines retires a read by rule; a re-read file is not forgotten by age again.\n      const rules = visible.filter(candidate => !ruled.has(candidate.seq) && estimate(candidate) > 0\n        && (superseded.has(candidate.seq) || (!isRead(candidate) && aged(candidate))))\n      const agedReads = visible.filter((candidate) => {\n        if (!isRead(candidate) || ruled.has(candidate.seq) || superseded.has(candidate.seq) || rereadOf(candidate) !== undefined) return false\n        const before = judgedBefore.get(candidate.seq)\n        return aged(candidate) && estimate(candidate) > 0 && (before === undefined || age(candidate) >= 2 * before)\n      })\n      // One cache rebuild has to buy enough: below this the results wait for the next batch.\n      if (sum(rules) + sum(agedReads) < config.minBatchChars) return\n      const batch = rules.slice(0, config.maxPerBatch)\n      // When the rules alone do not pay for a rebuild, they wait for the judge's verdicts on the reads.\n      const deferred = sum(batch) < config.minBatchChars\n      const inWindow = visible.filter(candidate => !ruled.has(candidate.seq) && !judgedBefore.has(candidate.seq) && !rules.includes(candidate)\n        && !isRead(candidate) && age(candidate) >= JUDGE_MIN_AGE && candidate.chars >= config.minChars && estimate(candidate) > 0)\n      const asked = [...agedReads, ...inWindow]\n      for (const candidate of batch) ruled.add(candidate.seq)\n      for (const candidate of asked) judgedBefore.set(candidate.seq, Math.max(1, age(candidate)))\n\n      const origin = { userMessageId: request?.id ?? task.userMessageId, results: state.results, steps: state.steps, keepRecent: config.keepRecent }\n      const rulesId = agentState.engine.recordRules(contextForget, {\n        state: { superseded: batch.filter(candidate => superseded.has(candidate.seq)).map(candidate => candidate.seq), aged: batch.filter(candidate => !superseded.has(candidate.seq)).map(candidate => candidate.seq) },\n        outcome: { forget: batch.map(candidate => candidate.seq) },\n        origin, applied: false, savedChars: sum(batch),\n      })\n      const bound = deadline(cancel, config.waitMs)\n      let judging: Promise<Decision<ForgetOutcome>[]> | undefined\n      try {\n        if (asked.length > 0) {\n          const goal = [...new Set([task.firstUser, current].filter(Boolean))].join('\\n')\n          judging = agentState.engine.decideMany(contextForget, asked.map(candidate => ({\n            goal, call: `${candidate.call?.name ?? 'tool'}: ${candidate.call?.arguments ?? ''}`.slice(0, 500),\n            resultChars: candidate.chars, resultsSince: state.results - candidate.ordinal, since: state.since, preview: preview(candidate),\n          })), { signal: mode === 'shadow' ? cancel : bound.signal, applied: false, origin })\n          void judging.then(decisions => {\n            const id = decisions[0]?.ledgerId\n            if (id === undefined) return\n            const savedChars = decisions.reduce((total, decision, index) => total + (decision.judged === 'shrink' && asked[index] !== undefined ? estimate(asked[index]) : 0), 0)\n            void host.track(host.annotate(sessionId, id, { savedChars }))\n          }).catch(() => {})\n        }\n        if (mode === 'shadow') return\n        const apply = async (selected: readonly ForgetCandidate[]): Promise<boolean> => {\n          let applied = false\n          for (const candidate of selected) {\n            if (!valid() || bound.signal.aborted || !onSurface(candidate.seq)) break\n            let ref\n            try {\n              ref = await untilAbort(host.track(ctx.spillStore.saveText({ owner: { sessionId },\n                source: { kind: 'tool', toolName: candidate.call?.name ?? 'tool', callId: candidate.data.message.toolCallId, label: 'sieve-forgotten' },\n                suggestedName: 'forgotten-output.txt', content: textOf(candidate.data.message.content),\n              })), bound.signal)\n            } catch { ctx.logger.warn('sieve: archive failed; keeping this tool result'); continue }\n            if (ref === undefined || !valid() || !onSurface(candidate.seq)) continue\n            const text = replacement(candidate, superseded.has(candidate.seq), config.edgeChars, ref.locator, ref.retrievalHint)\n            if (text.length >= candidate.chars) continue\n            const seq = SessionSeq(candidate.seq)\n            agent.session.append('compaction/prune', { shadowedRange: { start: seq, end: seq }, shadowedSeqs: [seq], shadowedTokenCount: estimateMessage(candidate.data.message) })\n            agent.session.append('tool/result', { ...candidate.data, message: freezeMessage<ToolResultMessage>({ ...candidate.data.message, content: [{ type: 'text', text }] }) }, {\n              surfaceOp: { op: 'replace', startSeq: seq, endSeq: seq }, sourceEventSeqs: [seq],\n            })\n            applied = true\n          }\n          return applied\n        }\n        const annotateRules = (applied: boolean): void => {\n          if (rulesId !== undefined) void host.track(host.annotate(sessionId, rulesId, { applied }))\n        }\n        // The rules get their archive budget even if the judge times out, once they pay for the rebuild themselves.\n        if (!deferred) annotateRules(await apply(batch))\n        const judged = judging === undefined ? undefined : await untilAbort(judging, bound.signal)\n        const chosen = judged === undefined ? [] : asked.filter((_, index) => judged[index]?.outcome === 'shrink')\n        if (deferred) {\n          if (!valid() || sum(batch) + sum(chosen) < config.minBatchChars) {\n            // Not worth a rebuild yet: the rule candidates are reconsidered when more accumulates.\n            for (const candidate of batch) ruled.delete(candidate.seq)\n            annotateRules(false)\n            return\n          }\n          annotateRules(await apply(batch))\n        }\n        if (!valid() || judged === undefined) return\n        const judgeApplied = await apply(chosen)\n        const judgeId = judged[0]?.ledgerId\n        if (judgeId !== undefined) void host.track(host.annotate(sessionId, judgeId, { applied: judgeApplied }))\n      } finally { bound.dispose() }\n    }\n    try { await run() } catch {\n      ctx.logger.warn('sieve: forgetting failed; keeping the current context')\n    }\n    return next()\n  }, { prepend: true })\n\n  /**\n   * Charge each re-read of a forgotten file once against the saving: the\n   * content is back in the context, so the forgetting saved nothing from here\n   * on. Applied in any mode, because the context did change. The ledger is\n   * checked too, so a resumed session does not charge twice.\n   */\n  function chargeRereads(agent: Agent, visible: readonly ForgetCandidate[], rereadOf: (candidate: ForgetCandidate) => ForgottenRead | undefined): void {\n    let seen = charged.get(agent)\n    if (seen === undefined) { seen = new Set(); charged.set(agent, seen) }\n    const sessionId = agent.session.header.id\n    for (const candidate of visible) {\n      const entry = rereadOf(candidate)\n      if (entry === undefined || seen.has(entry.seq)) continue\n      seen.add(entry.seq)\n      const recorded = host.ledger(sessionId).some(record => record.specId === contextForget.id\n        && typeof record.origin === 'object' && record.origin !== null && 'reread' in record.origin && record.origin.reread === entry.seq)\n      if (recorded) continue\n      runtime.for(agent).engine.recordRules(contextForget, {\n        state: { reread: candidate.seq, forgotten: entry.seq },\n        outcome: { reread: candidate.seq },\n        origin: { reread: entry.seq },\n        applied: true, savedChars: -Math.min(candidate.chars, entry.saved),\n      })\n    }\n  }\n}\n"
    },
    {
      "path": "packages/dsh-sieve/src/features/skills.ts",
      "content": "/**\n * Task-based skill catalog disclosure.\n * Contains MIT-licensed third-party code, see THIRD_PARTY_NOTICES.md.\n */\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent, PreStepDecision } from '@deepseek-ai/dsh-agent'\nimport type { UserMessage } from '@deepseek-ai/dsh-llm'\nimport type { SessionEvent } from '@deepseek-ai/dsh-session'\nimport type { SkillCatalogSource } from '@deepseek-ai/dsh-tool-skill'\nimport { z } from 'zod'\nimport { skillDisclosure } from '../judge/decisions/skill-disclosure.ts'\nimport type { Decision } from '../judge/engine.ts'\nimport type { SkillDisclosureOutcome } from '../judge/decisions/skill-disclosure.ts'\nimport { deadline, untilAbort } from '../runtime/operations.ts'\nimport { textOf } from '../runtime/session-state.ts'\nimport type { SessionRuntime } from '../runtime/session-state.ts'\nimport type { AdmissionHost } from './admission.ts'\n\nexport const SKILL_STATE_KEY = 'sieve/skills'\ntype Entries = SkillCatalogSource['entries']\n\n/** Metadata rides on an existing native catalog message; adapters never see it. */\ndeclare module '@deepseek-ai/dsh-tool-skill' {\n  interface SkillCatalogSource {\n    readonly sieveHidden?: readonly string[]\n  }\n}\n\nexport interface CatalogState {\n  published: boolean\n  visible: { seq: number, entries: Entries } | null\n  hidden: string[]\n}\n\ndeclare module '@deepseek-ai/dsh-session-projection/types' {\n  interface SessionProjectionStateMap {\n    'sieve/skills': CatalogState\n  }\n}\n\nfunction fold(state: CatalogState, event: SessionEvent): CatalogState {\n  const op = event.surfaceOp\n  let visible = state.visible\n  if (typeof op === 'object' && visible !== null && visible.seq >= op.startSeq && visible.seq <= op.endSeq) visible = null\n  if (event.type === 'user/message' && event.data.source.kind === 'skill-catalog') {\n    const source = event.data.source\n    return { published: true, visible: { seq: event.seq, entries: source.entries }, hidden: [...source.sieveHidden ?? []] }\n  }\n  return visible === state.visible ? state : { ...state, visible }\n}\n\nfunction named(text: string, name: string): boolean {\n  const escaped = name.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\n  return new RegExp(`(?:^|[^\\\\w-])${escaped}(?=$|[^\\\\w-])`, 'i').test(text)\n}\n\nfunction filterCatalog(catalog: UserMessage, hidden: ReadonlySet<string>): UserMessage {\n  if (catalog.source.kind !== 'skill-catalog') return catalog\n  return {\n    ...catalog,\n    source: { ...catalog.source, entries: catalog.source.entries.filter(entry => !hidden.has(entry.name)), sieveHidden: [...hidden] },\n    content: catalog.content.map(block => block.type !== 'text' ? block : {\n      ...block,\n      text: block.text.split('\\n').filter(line => ![...hidden].some(name => line.startsWith(`- \\`${name}\\`: `))).join('\\n'),\n    }),\n  }\n}\n\nexport function registerSkills(ctx: Context, host: AdmissionHost, runtime: SessionRuntime): void {\n  ctx.sessionProjections.register({\n    key: SKILL_STATE_KEY, stateVersion: 1,\n    stateSchema: z.custom<CatalogState>(value => typeof value === 'object' && value !== null && 'published' in value),\n    init: () => ({ published: false, visible: null, hidden: [] }), apply: fold,\n  })\n  const handled = new WeakMap<Agent, string>()\n  // Applied is confirmed only once the rewritten catalog actually commits.\n  const receipts = new WeakMap<Agent, { messageId: string, ledgerId: string }>()\n  ctx.on('session/event', (session, event) => {\n    if (event.type !== 'user/message' || event.data.source.kind !== 'skill-catalog') return\n    for (const agent of ctx.get('agents')?.list() ?? []) {\n      const receipt = receipts.get(agent)\n      if (agent.session !== session || receipt?.messageId !== event.data.id) continue\n      receipts.delete(agent)\n      void host.track(host.annotate(session.header.id, receipt.ledgerId, { applied: true }))\n    }\n  })\n\n  ctx.on('agent/pre-step', async ({ agent, messages, signal }, next): Promise<PreStepDecision> => {\n    const decision = await next()\n    if (decision.kind !== 'enter' || !host.config.skillDisclosure.enabled) return decision\n    try {\n      const config = host.config.skillDisclosure\n      const engine = runtime.for(agent).engine\n      const mode = engine.modeOf(skillDisclosure.id)\n      if (mode === 'off' || !await host.judgeReady()) return decision\n      const index = decision.messages.findIndex(message => message.source.kind === 'skill-catalog')\n      const catalog = decision.messages[index]\n      if (catalog?.source.kind !== 'skill-catalog') return decision\n      const state = ctx.sessionProjections.stateOf(agent.session, SKILL_STATE_KEY)\n      if (state === undefined) return decision\n      const task = runtime.task(agent)\n      const incoming = [...messages].reverse().find(message => message.source.kind === 'user')\n      const words = incoming === undefined ? task?.lastUser ?? '' : textOf(incoming.content)\n      const requestId = incoming?.id ?? task?.userMessageId ?? ''\n      const cancel = AbortSignal.any([signal, runtime.for(agent).controller.signal])\n      const revision = task?.revision\n      const settings = host.revisionOf(agent.session.header.id)\n      const valid = (): boolean => !cancel.aborted && runtime.task(agent)?.revision === revision && host.revisionOf(agent.session.header.id) === settings\n      let hidden = new Set(state.hidden.filter(name => catalog.source.kind === 'skill-catalog' && catalog.source.entries.some(entry => entry.name === name)))\n      const eligible = catalog.source.entries.length >= config.minSkills && catalog.source.entries.length <= config.maxSkills && words.trim() !== ''\n      const first = !state.published\n      const revealNamed = [...hidden].filter(name => named(words, name) || config.alwaysVisible.includes(name))\n      if (mode === 'active') for (const name of revealNamed) hidden.delete(name)\n      const shouldJudge = eligible && handled.get(agent) !== requestId && (first || (incoming !== undefined && hidden.size > 0))\n      let judged: Decision<SkillDisclosureOutcome> | undefined\n      if (shouldJudge) {\n        handled.set(agent, requestId)\n        const candidates = first ? catalog.source.entries : catalog.source.entries.filter(entry => hidden.has(entry.name))\n        if (candidates.length > 0) {\n          // The judge splits a large catalog into requests of its own size; the catalog is still one decision.\n          const input = { userMessage: words, skills: candidates }\n          const work = engine.decide(skillDisclosure, input, { signal: cancel, applied: false, origin: { userMessageId: requestId, firstCatalog: first } })\n          const estimate = (value: Decision<SkillDisclosureOutcome>): void => {\n            if (value.ledgerId === undefined) return\n            const omitted = first ? new Set(value.judged?.hide.filter(name => !named(words, name) && !config.alwaysVisible.includes(name)) ?? []) : new Set<string>()\n            const chars = textOf(catalog.content).length - textOf(filterCatalog(catalog, omitted).content).length\n            void host.track(host.annotate(agent.session.header.id, value.ledgerId, { savedChars: chars }))\n          }\n          void work.then(estimate).catch(() => {})\n          if (mode === 'active') {\n            const bound = deadline(cancel, config.waitMs)\n            try { judged = await untilAbort(work, bound.signal) } finally { bound.dispose() }\n            if (!valid()) return decision\n            if (judged?.source === 'judge') {\n              if (first) hidden = new Set(judged.outcome.hide.filter(name => !named(words, name) && !config.alwaysVisible.includes(name)))\n              else for (const name of judged.outcome.relevant) hidden.delete(name)\n            }\n          }\n        }\n      }\n      if (mode === 'shadow') return decision\n      if (!valid()) return decision\n      const rewritten = filterCatalog(catalog, hidden)\n      const entries = rewritten.source.kind === 'skill-catalog' ? rewritten.source.entries : []\n      if (state.visible !== null && JSON.stringify(entries) === JSON.stringify(state.visible.entries) && JSON.stringify([...hidden]) === JSON.stringify(state.hidden)) {\n        return { ...decision, messages: decision.messages.filter((_, at) => at !== index) }\n      }\n      const judgeChanged = judged?.source === 'judge' && (first ? hidden.size > 0\n        : state.hidden.some(name => judged.outcome.relevant.includes(name) && !hidden.has(name)))\n      if (judged?.ledgerId !== undefined && judgeChanged) {\n        receipts.set(agent, { messageId: rewritten.id, ledgerId: judged.ledgerId })\n      }\n      return { ...decision, messages: decision.messages.map((message, at) => at === index ? rewritten : message) }\n    } catch {\n      ctx.logger.warn('sieve: skill disclosure failed; keeping the DSH catalog')\n      return decision\n    }\n  }, { prepend: true })\n}\n"
    },
    {
      "path": "packages/dsh-sieve/src/runtime/config.ts",
      "content": "/**\n * sieve's profile configuration: which judge answers, in which mode each\n * decision runs, and what the ledger keeps. The schema carries the defaults;\n * `resolveConfig` rejects what the schema cannot express, so a bad profile\n * fails at load instead of silently falling back.\n * @module\n */\n\nimport z from '@deepseek-ai/schemastery'\nimport { DECISION_MODES } from '../judge/decision.ts'\nimport type { DecisionMode } from '../judge/decision.ts'\n\n/**\n * The registered decisions: the first release's four (migration plan §1) and\n * the harness modules' (docs/plan-harness-modules.md).\n */\nexport const DECISION_IDS = [\n  'tool.admission', 'tool.admission.test-log', 'context.forget', 'skills.disclosure',\n  'hive.publish', 'hive.deliver', 'hive.relate', 'swarm.routing',\n  'goal.met', 'turn.completion', 'turn.drift',\n  'turn.rewind', 'resume.safety',\n  'tool.approval', 'tool.risk',\n  'team.release', 'team.verify', 'team.conflict', 'team.dispatch',\n] as const\nexport type DecisionId = typeof DECISION_IDS[number]\n\n/**\n * Decisions that start in `shadow` until their ledger shows they judge well\n * (plan D5): they change what an agent does. A profile `default` can only\n * lower them (to `off`); a per-decision entry sets them outright.\n */\nconst SHADOW_BY_DEFAULT: ReadonlySet<DecisionId> = new Set<DecisionId>([\n  'goal.met', 'turn.completion', 'turn.drift',\n  'team.release', 'team.verify', 'team.conflict', 'team.dispatch',\n])\n\nconst MODE_RANK: Readonly<Record<DecisionMode, number>> = { off: 0, shadow: 1, active: 2 }\n\n/** Node caps timers at 2^31 - 1 ms. */\nconst MAX_TIMER_DELAY_MS = 2_147_483_647\n\nexport type JudgeType = 'auto' | 'system-one' | 'laya'\n\n/**\n * sieve runs only with a dedicated judge model, Jev or Laya; the session's own\n * model never stands in (user decision, 2026-10-08). Without one, no decision\n * changes anything, rules included.\n */\nexport interface JudgeConfig {\n  /**\n   * `auto` (default): Jev over System One with the key DSH's credential store\n   * holds (see `runtime/jev.ts`), resolved per call; no key, no judgment.\n   * `system-one`: Jev over HTTP (TypeSafe or OpenRouter), needs `apiKey`.\n   * `laya`: the local Laya sidecar, no key.\n   */\n  type: JudgeType\n  /** system-one: judge model, default `jev-latest`. */\n  model?: string\n  /** system-one: endpoint, default TypeSafe's. laya: the sidecar, default `http://127.0.0.1:47823`. */\n  baseUrl?: string\n  /** system-one: the key, e.g. `!!js process.env.TYPESAFE_API_KEY`. */\n  apiKey?: string\n  /** Deadline of one judge call, end to end. */\n  timeoutMs: number\n}\n\nexport interface Config {\n  judge: JudgeConfig\n  /** Mode per decision id; `default` (itself `active` unless set) covers the rest. */\n  modes: Record<string, DecisionMode>\n  /** Store submitted judge states in the ledger. Off by default because states can hold user content. */\n  recordState: boolean\n  admission: AdmissionConfig\n  forgetting: ForgettingConfig\n  skillDisclosure: SkillDisclosureConfig\n  hive: HiveConfig\n  monitor: MonitorConfig\n  checkpoint: CheckpointConfig\n  resume: ResumeConfig\n  approval: ApprovalConfig\n  team: TeamConfig\n}\n\n/**\n * The team supervisor (plan §4 phase 6). It loads only where DSH's agent team\n * is mounted, and its actions start in shadow (D5).\n */\nexport interface TeamConfig {\n  enabled: boolean\n  /** Monitor signals (loop, stall, drift) after which a member is interrupted and its tasks released. */\n  stuckAfter: number\n  /** Start a read-only verifier when `team.verify` cannot settle a completed task. */\n  verifier: boolean\n  /** Minutes a verifier may run before it is stopped and the task left as it is; 0 means no limit. */\n  verifierMinutes: number\n}\n\n/**\n * Jev approval (plan §4 phase 3). Off by default (D2): a wrong approval cannot\n * be taken back, and owning DSH's single Auto preset excludes auto-review.\n * Turned on, it acts only in sessions the user switches to Auto.\n */\nexport interface ApprovalConfig {\n  enabled: boolean\n}\n\n/** Crash-resume classification (plan §4 phase 5). */\nexport interface ResumeConfig {\n  enabled: boolean\n}\n\n/** The hive (plan §4 phase 1); defaults are mu's. */\nexport interface HiveConfig {\n  enabled: boolean\n  maxBees: number\n  /** Bees running at once; the rest wait for a slot. */\n  concurrency: number\n  maxNotesPerBee: number\n  maxDeliveriesPerBee: number\n  /** Earlier notes a new one is held against, at most. */\n  maxRelatedPerNote: number\n  /**\n   * `judged`: the judge picks what is posted and who receives it. `broadcast`:\n   * every step's candidates are posted and handed to every other bee, with no\n   * judge and no corrections, still within the caps above; it exists for the\n   * ablation against the judged hive.\n   */\n  sharing: 'judged' | 'broadcast'\n  /** Tool calls a bee may make in silence before it is asked what it has found; 0 turns checkpoints off. */\n  checkpointEvery: number\n  /** Notes that arrive while a bee writes its report get one hearing: a corrected report, or \"NO CHANGE\". */\n  lastCall: boolean\n  /** Verifiers the hive may add for disputes nobody settles (0 turns it off), and how long a dispute may stand first. */\n  verifyConflicts: number\n  verifyAfterSeconds: number\n  /** Minutes a bee may work before it is told to wrap up and its tools close; 0 means no budget. */\n  beeMinutes: number\n  /** Seconds it then has to hand in its report before it is stopped. */\n  graceSeconds: number\n  /** Seconds without a sign of life before a bee is stopped: while its model works, and while a tool runs. */\n  stallSeconds: number\n  toolStallSeconds: number\n  /**\n   * Model ladder from cheapest to strongest, each `provider/model` (the first\n   * `/` separates them). Empty: every bee runs on the parent's model and\n   * `swarm.routing` is not asked.\n   */\n  models: string[]\n  /** The route's reasoning-effort id for each thinking level `swarm.routing` picks; unset levels keep the parent's. */\n  efforts: { low?: string, medium?: string, high?: string }\n}\n\n/** Long-task monitoring (plan §4 phase 2); cadences are mu's. */\nexport interface MonitorConfig {\n  enabled: boolean\n  /** How long the end of a turn and `update_goal complete` wait for an active verdict; defaults to the judge deadline. */\n  waitMs: number\n  /** Tool results between two drift questions while a goal is active. */\n  every: number\n  /** Results in a row of the same call ending the same way that make a loop. */\n  repeats: number\n  /** Recent actions the drift question reads. */\n  window: number\n  /** Loops of `repeats` results in a row after which an active goal is blocked as stalled. */\n  stallLoops: number\n}\n\n/** Checkpoints of the working tree and the judged rewind (plan §4 phase 4); limits are mu's. */\nexport interface CheckpointConfig {\n  enabled: boolean\n  /**\n   * Where the shadow repositories live, one per project. The bundle sets\n   * `dshHomePath('sieve', 'checkpoints')`; empty leaves checkpoints off.\n   */\n  root: string\n  /** Snapshots kept per project, and for how long. */\n  keep: number\n  maxAgeDays: number\n  /** Larger files stay out of snapshots and are never touched by a rewind. */\n  maxFileMb: number\n  /** A first snapshot past either limit is not taken, and the session goes without checkpoints. */\n  maxFiles: number\n  maxTotalMb: number\n  /** gitignore-style patterns on top of the project's own and the built-in list. */\n  ignore: string[]\n  /** Deadline of one git command. */\n  timeoutMs: number\n  /** Ask `turn.rewind` when the agent goes in circles, and propose going back. */\n  propose: boolean\n  /** A shell command that fails this many times in one turn asks `turn.rewind`. */\n  failures: number\n}\n\nexport interface ForgettingConfig {\n  enabled: boolean\n  /** The most recent tool results stay whole; older ones of at least `minChars` are forgotten. */\n  keepRecent: number\n  minChars: number\n  /**\n   * Forgetting rewrites history and costs the cached prefix from the first\n   * replaced result on, so it waits until one batch saves at least this many\n   * characters.\n   */\n  minBatchChars: number\n  /** Characters of a forgotten result kept at each end. */\n  edgeChars: number\n  maxPerBatch: number\n  waitMs: number\n  maxTrackedResults: number\n  maxStateChars: number\n}\n\nexport interface SkillDisclosureConfig {\n  enabled: boolean\n  minSkills: number\n  maxSkills: number\n  waitMs: number\n  alwaysVisible: string[]\n}\n\nexport interface AdmissionConfig {\n  enabled: boolean\n  minChars: number\n  judgeMinChars: number\n  chunkChars: number\n  maxChunks: number\n  waitMs: number\n  testLog: 'off' | 'rules' | 'judge'\n  /** Replace runs that repeat text the model still sees with a reference. Lossless while the source stays. */\n  dedup: boolean\n  /** Fold runs of lines that differ at most in numbers. */\n  foldSimilar: boolean\n  minNetChars: number\n  minNetShare: number\n  /** Tools whose output is never touched. */\n  passThrough: string[]\n  /** Tools whose output is file content: only `dedup` applies, nothing lossy. */\n  contentTools: string[]\n}\n\nexport const Config: z<Config> = z.object({\n  judge: z.object({\n    type: z.union(['auto', 'system-one', 'laya'] as const).default('auto'),\n    model: z.string(),\n    baseUrl: z.string(),\n    apiKey: z.string(),\n    timeoutMs: z.natural().min(1).max(MAX_TIMER_DELAY_MS).default(4000),\n  }).default({}),\n  modes: z.dict(z.union(DECISION_MODES)).default({}),\n  recordState: z.boolean().default(false),\n  admission: z.object({\n    enabled: z.boolean().default(true),\n    minChars: z.natural().min(1).default(1500),\n    judgeMinChars: z.natural().min(1).default(8000),\n    chunkChars: z.natural().min(1).default(1200),\n    maxChunks: z.natural().min(3).max(48).default(48),\n    waitMs: z.natural().min(1).max(MAX_TIMER_DELAY_MS),\n    testLog: z.union(['off', 'rules', 'judge'] as const).default('rules'),\n    dedup: z.boolean().default(true),\n    foldSimilar: z.boolean().default(true),\n    minNetChars: z.natural().min(1).default(300),\n    minNetShare: z.number().min(0).max(1).default(0.1),\n    passThrough: z.array(z.string()).default(['read_image', 'subagent', 'delegate']),\n    contentTools: z.array(z.string()).default(['read', 'edit', 'write', 'str_replace_editor']),\n  }).default({}),\n  forgetting: z.object({\n    enabled: z.boolean().default(true),\n    keepRecent: z.natural().min(1).default(4),\n    minChars: z.natural().min(1).default(1500),\n    minBatchChars: z.natural().min(1).default(10_000),\n    edgeChars: z.natural().default(300),\n    maxPerBatch: z.natural().min(1).max(128).default(64),\n    waitMs: z.natural().min(1).max(MAX_TIMER_DELAY_MS),\n    maxTrackedResults: z.natural().min(1).max(1024).default(128),\n    maxStateChars: z.natural().min(1).default(2_000_000),\n  }).default({}),\n  skillDisclosure: z.object({\n    enabled: z.boolean().default(true),\n    minSkills: z.natural().min(1).default(3),\n    maxSkills: z.natural().min(1).max(256).default(256),\n    waitMs: z.natural().min(1).max(MAX_TIMER_DELAY_MS),\n    alwaysVisible: z.array(z.string()).default([]),\n  }).default({}),\n  hive: z.object({\n    enabled: z.boolean().default(true),\n    maxBees: z.natural().min(2).max(16).default(6),\n    concurrency: z.natural().min(1).max(16).default(4),\n    maxNotesPerBee: z.natural().default(12),\n    maxDeliveriesPerBee: z.natural().default(10),\n    maxRelatedPerNote: z.natural().default(6),\n    sharing: z.union(['judged', 'broadcast'] as const).default('judged'),\n    checkpointEvery: z.natural().default(4),\n    lastCall: z.boolean().default(true),\n    verifyConflicts: z.natural().max(4).default(1),\n    verifyAfterSeconds: z.natural().min(1).default(60),\n    beeMinutes: z.natural().default(10),\n    graceSeconds: z.natural().min(1).default(90),\n    stallSeconds: z.natural().min(1).default(300),\n    toolStallSeconds: z.natural().min(1).default(900),\n    models: z.array(z.string()).default([]),\n    efforts: z.object({ low: z.string(), medium: z.string(), high: z.string() }).default({}),\n  }).default({}),\n  monitor: z.object({\n    enabled: z.boolean().default(true),\n    waitMs: z.natural().min(1).max(MAX_TIMER_DELAY_MS),\n    every: z.natural().min(1).default(6),\n    repeats: z.natural().min(2).default(3),\n    window: z.natural().min(1).max(32).default(8),\n    stallLoops: z.natural().min(2).default(2),\n  }).default({}),\n  checkpoint: z.object({\n    enabled: z.boolean().default(true),\n    root: z.string().default(''),\n    keep: z.natural().min(1).default(50),\n    maxAgeDays: z.natural().min(1).default(14),\n    maxFileMb: z.number().min(0).default(5),\n    maxFiles: z.natural().min(1).default(5000),\n    maxTotalMb: z.number().min(0).default(200),\n    ignore: z.array(z.string()).default([]),\n    timeoutMs: z.natural().min(1).max(MAX_TIMER_DELAY_MS).default(30_000),\n    propose: z.boolean().default(true),\n    failures: z.natural().min(2).default(3),\n  }).default({}),\n  resume: z.object({\n    enabled: z.boolean().default(true),\n  }).default({}),\n  approval: z.object({\n    enabled: z.boolean().default(false),\n  }).default({}),\n  team: z.object({\n    enabled: z.boolean().default(true),\n    stuckAfter: z.natural().min(1).default(2),\n    verifier: z.boolean().default(true),\n    verifierMinutes: z.number().min(0).max(MAX_TIMER_DELAY_MS / 60_000).default(10),\n  }).default({}),\n})\n\nexport type ResolvedJudge =\n  | {\n    /** Jev with the credential store's key, resolved per call. */\n    readonly type: 'auto'\n    readonly timeoutMs: number\n  }\n  | {\n    readonly type: 'system-one'\n    readonly apiKey: string\n    readonly baseUrl: string | undefined\n    readonly model: string | undefined\n    readonly timeoutMs: number\n  }\n  | {\n    readonly type: 'laya'\n    readonly baseUrl: string | undefined\n    readonly timeoutMs: number\n  }\n\nexport interface ResolvedConfig {\n  readonly judge: ResolvedJudge\n  readonly defaultMode: DecisionMode\n  readonly modes: ReadonlyMap<DecisionId, DecisionMode>\n  readonly recordState: boolean\n  readonly admission: Readonly<Omit<AdmissionConfig, 'passThrough' | 'contentTools'>> & { readonly passThrough: readonly string[], readonly contentTools: readonly string[] }\n  readonly forgetting: Readonly<ForgettingConfig>\n  readonly skillDisclosure: Readonly<Omit<SkillDisclosureConfig, 'alwaysVisible'>> & { readonly alwaysVisible: readonly string[] }\n  readonly hive: ResolvedHiveConfig\n  readonly monitor: Readonly<MonitorConfig>\n  readonly checkpoint: Readonly<Omit<CheckpointConfig, 'ignore'>> & { readonly ignore: readonly string[] }\n  readonly resume: Readonly<ResumeConfig>\n  readonly approval: Readonly<ApprovalConfig>\n  readonly team: Readonly<TeamConfig>\n}\n\nexport interface ModelRoute {\n  readonly provider: string\n  readonly model: string\n}\n\nexport type ResolvedHiveConfig = Readonly<Omit<HiveConfig, 'models' | 'efforts'>> & {\n  readonly models: readonly ModelRoute[]\n  readonly efforts: Readonly<HiveConfig['efforts']>\n}\n\n/** `provider/model`, split at the first `/`. */\nexport function parseModelRoute(entry: string): ModelRoute {\n  const at = entry.indexOf('/')\n  if (at <= 0 || at === entry.length - 1) throw new Error(`sieve: hive.models entry \"${entry}\" is not provider/model`)\n  return { provider: entry.slice(0, at), model: entry.slice(at + 1) }\n}\n\n/** The mode a profile gives a decision: its own entry, else the default, which only lowers a shadow-by-default decision. */\nexport function profileModeOf(config: Pick<ResolvedConfig, 'modes' | 'defaultMode'>, id: DecisionId): DecisionMode {\n  const own = config.modes.get(id)\n  if (own !== undefined) return own\n  if (!SHADOW_BY_DEFAULT.has(id)) return config.defaultMode\n  return MODE_RANK[config.defaultMode] < MODE_RANK.shadow ? config.defaultMode : 'shadow'\n}\n\nconst MODE_KEYS: ReadonlySet<string> = new Set(['default', ...DECISION_IDS])\n\nfunction nonEmpty(value: string | undefined): string | undefined {\n  return value === undefined || value === '' ? undefined : value\n}\n\n/**\n * Validate a configuration and detach it from the caller.\n * @param config - raw or schema-validated configuration.\n * @returns the immutable configuration sieve runs on.\n */\nexport function resolveConfig(config: Partial<Config> | undefined): ResolvedConfig {\n  // The schema drops unknown keys; a profile written for the removed session-model judge must not load as if it worked.\n  const raw = (config ?? {}) as Record<string, unknown>\n  const rawJudge = typeof raw['judge'] === 'object' && raw['judge'] !== null ? raw['judge'] as Record<string, unknown> : {}\n  if (rawJudge['type'] === 'llm' || rawJudge['type'] === 'off' || 'routes' in raw || 'provider' in rawJudge || 'maxOutputTokens' in rawJudge) {\n    throw new Error('sieve: the session-model judge was removed (judge.type llm or off, judge.provider, judge.maxOutputTokens, routes); configure Jev or Laya')\n  }\n\n  const value = Config((config ?? {}) as Config)\n  const judge = value.judge\n\n  let resolved: ResolvedJudge\n  if (judge.type === 'auto') {\n    resolved = { type: 'auto', timeoutMs: judge.timeoutMs }\n  } else if (judge.type === 'laya') {\n    resolved = { type: 'laya', baseUrl: nonEmpty(judge.baseUrl), timeoutMs: judge.timeoutMs }\n  } else {\n    const apiKey = nonEmpty(judge.apiKey)\n    if (apiKey === undefined) throw new Error('sieve: judge.type system-one needs judge.apiKey')\n    resolved = {\n      type: 'system-one',\n      apiKey,\n      baseUrl: nonEmpty(judge.baseUrl),\n      model: nonEmpty(judge.model),\n      timeoutMs: judge.timeoutMs,\n    }\n  }\n\n  const modes = new Map<DecisionId, DecisionMode>()\n  if ('thresholds' in value.forgetting || 'minAgeTurns' in value.forgetting) {\n    throw new Error('sieve: forgetting.thresholds and minAgeTurns were replaced by keepRecent and minBatchChars')\n  }\n  if (value.skillDisclosure.maxSkills < value.skillDisclosure.minSkills) throw new Error('sieve: skillDisclosure.maxSkills must be at least minSkills')\n  for (const [key, mode] of Object.entries(value.modes)) {\n    if (!MODE_KEYS.has(key)) {\n      throw new Error(`sieve: unknown decision \"${key}\" in modes; known: default, ${DECISION_IDS.join(', ')}`)\n    }\n    if (key !== 'default') modes.set(key as DecisionId, mode)\n  }\n\n  return Object.freeze({\n    judge: Object.freeze(resolved),\n    // Active unless the profile says otherwise (user decision, 2026-10-06).\n    defaultMode: value.modes['default'] ?? 'active',\n    modes,\n    recordState: value.recordState,\n    admission: Object.freeze({\n      ...value.admission,\n      waitMs: value.admission.waitMs ?? Math.min(MAX_TIMER_DELAY_MS, judge.timeoutMs + 1000),\n      passThrough: Object.freeze([...value.admission.passThrough]),\n      contentTools: Object.freeze([...value.admission.contentTools]),\n    }),\n    forgetting: Object.freeze({ ...value.forgetting, waitMs: value.forgetting.waitMs ?? Math.min(MAX_TIMER_DELAY_MS, judge.timeoutMs + 1000) }),\n    skillDisclosure: Object.freeze({ ...value.skillDisclosure, waitMs: value.skillDisclosure.waitMs ?? judge.timeoutMs, alwaysVisible: Object.freeze([...value.skillDisclosure.alwaysVisible]) }),\n    hive: Object.freeze({\n      ...value.hive,\n      models: Object.freeze(value.hive.models.map(parseModelRoute)),\n      efforts: Object.freeze(Object.fromEntries(Object.entries(value.hive.efforts).filter(([, effort]) => nonEmpty(effort) !== undefined))),\n    }),\n    monitor: Object.freeze({ ...value.monitor, waitMs: value.monitor.waitMs ?? judge.timeoutMs }),\n    checkpoint: Object.freeze({ ...value.checkpoint, ignore: Object.freeze([...value.checkpoint.ignore]) }),\n    resume: Object.freeze({ ...value.resume }),\n    approval: Object.freeze({ ...value.approval }),\n    team: Object.freeze({ ...value.team }),\n  })\n}\n"
    },
    {
      "path": "packages/dsh-sieve/src/features/checkpoint/index.ts",
      "content": "/**\n * Checkpoints of the working tree, and a rewind the judge may propose.\n *\n * Before the first tool call of a turn that can change files, the project is\n * snapshotted into its shadow repository (`runtime/checkpoint/store.ts`) and\n * the snapshot is noted in the `sieve_checkpoints` index with the seq the\n * turn began after. `/sieve rewind` puts the files back (after a snapshot of\n * the present, so `/sieve rewind undo` can take it back) and forks the\n * conversation into a new session at that seq (D3). When the monitor sees the\n * agent go in circles, or one shell command keeps failing, `turn.rewind` asks\n * the judge whether this is a dead end; a confident yes adds one notice that\n * names the checkpoint. Nothing here rewinds on its own, and any failure\n * leaves DSH's plain behavior.\n *\n * A project goes without checkpoints where a snapshot would copy what is no\n * project: the home folder (or one that holds it), sieve's own folder, or a\n * first snapshot past `maxFiles` / `maxTotalMb`. A machine whose git cannot\n * run goes without them altogether. `/sieve checkpoints` and the status say\n * why.\n *\n * Ported from mu `packages/kyrn-judge/src/extension/features/checkpoint.ts`;\n * pi's tree navigation became a DSH fork, its dialogs became the words of\n * the command, and its writer-model lesson became a fixed notice.\n * Contains MIT-licensed third-party code, see THIRD_PARTY_NOTICES.md.\n * @module\n */\n\nimport { randomUUID } from 'node:crypto'\nimport { homedir } from 'node:os'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport { SessionId, SessionLogOffset, SessionSeq, buildForkSeed } from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-session-query'\nimport type {} from '@deepseek-ai/dsh-tools'\nimport type {} from '@deepseek-ai/dsh-working-directory'\nimport type { Decision } from '../../judge/engine.ts'\nimport { turnRewind } from '../../judge/decisions/turn-rewind.ts'\nimport type { RewindOutcome } from '../../judge/decisions/turn-rewind.ts'\nimport { clip } from '../../judge/hive/member.ts'\nimport { isMutatingCall } from '../../judge/monitor/mutating.ts'\nimport type { Sieve } from '../../index.ts'\nimport { GitMissing, GitUnusable, UNUSABLE_TEXT, spawnGit } from '../../runtime/checkpoint/git.ts'\nimport type { GitRun } from '../../runtime/checkpoint/git.ts'\nimport {\n  BUILT_IN_IGNORES,\n  SnapshotTooLarge,\n  applyRestore,\n  collectGarbage,\n  diff,\n  hasCommit,\n  isWithin,\n  openStore,\n  planRestore,\n  prune,\n  releaseLocks,\n  scan,\n  snapshot,\n  sweepProjects,\n} from '../../runtime/checkpoint/store.ts'\nimport type { RestorePlan, RestoreResult, ScanLimits, Store } from '../../runtime/checkpoint/store.ts'\nimport { untilAbort } from '../../runtime/operations.ts'\nimport type { SessionRuntime } from '../../runtime/session-state.ts'\nimport type {} from '../../runtime/signals.ts'\nimport { sieveNotice } from '../../runtime/sources.ts'\nimport type { SieveCheckpointStatus } from '../../status.ts'\nimport { CHECKPOINT_STATE_KEY, registerTurnFacts } from './facts.ts'\nimport type { TurnFacts } from './facts.ts'\nimport { CheckpointIndex, checkpointDomain } from './records.ts'\nimport type { CheckpointRecord, RewindRecord, RewindScope } from './records.ts'\n\n/**\n * Why checkpoints are off. `no_root`: the profile names no folder for them.\n * The machine's git says `git_missing`, `xcode_license`,\n * `developer_tools_missing`; the folder says `home_folder` and `own_folder`;\n * the first snapshot says the size ones, and stops before it writes anything.\n */\nexport type CheckpointsOff =\n  | 'no_root'\n  | 'no_index'\n  | 'git_missing'\n  | 'xcode_license'\n  | 'developer_tools_missing'\n  | 'home_folder'\n  | 'own_folder'\n  | 'too_many_files'\n  | 'too_many_bytes'\n  | 'too_slow'\n\nconst MAX_LISTED = 12\n/** How many times one turn asks `turn.rewind`. */\nconst MAX_ASKED = 2\n\nexport interface CheckpointDeps {\n  /** How git is run. Tests stand in for a machine without git. */\n  readonly run?: GitRun\n  /** The user's home folder: no checkpoints of it or of what holds it. */\n  readonly home?: string\n}\n\ninterface Project {\n  readonly root: string\n  store: Promise<Store> | undefined\n  /** One shadow command at a time: they share an index. */\n  chain: Promise<unknown>\n  busy: number\n  /** Off for this folder, for the rest of the process. */\n  off: CheckpointsOff | undefined\n}\n\ninterface Pending {\n  readonly message: ReturnType<typeof sieveNotice>\n  readonly turn: number\n  readonly ledgerId: string | undefined\n}\n\ninterface Live {\n  turn: number\n  /** The snapshot of this turn, taken or being taken. */\n  taking: Promise<CheckpointRecord | undefined> | undefined\n  checkpoint: CheckpointRecord | undefined\n  /** The monitor's latest word about this turn. */\n  trouble: string | undefined\n  /** The trigger last asked about, so one trigger is asked once. */\n  askedAbout: string | undefined\n  asked: number\n  asking: boolean\n  proposed: { readonly id: number, readonly trigger: string, readonly at: string } | undefined\n  queue: Pending[]\n}\n\nconst listed = (paths: readonly string[]): string =>\n  paths.length <= MAX_LISTED ? paths.join(', ') : `${paths.slice(0, MAX_LISTED).join(', ')} 等 ${paths.length} 个`\n\n/** What a rewind would do to the files, in words. Relative paths and counts only. */\nexport function describePlan(plan: RestorePlan, keep: ReadonlySet<string> = new Set()): string {\n  const acting = (paths: readonly string[]) => paths.filter(path => !keep.has(path))\n  const lines = [\n    acting(plan.restore).length > 0 ? `改回 ${acting(plan.restore).length} 个：${listed(acting(plan.restore))}` : '',\n    acting(plan.remove).length > 0 ? `删除之后新建的 ${acting(plan.remove).length} 个：${listed(acting(plan.remove))}` : '',\n    acting(plan.bringBack).length > 0 ? `找回之后删掉的 ${acting(plan.bringBack).length} 个：${listed(acting(plan.bringBack))}` : '',\n    keep.size > 0 ? `保留手动改过的 ${keep.size} 个：${listed([...keep])}` : '',\n    plan.leftAlone.length > 0 ? `不动 ${plan.leftAlone.length} 个：${listed(plan.leftAlone.map(entry => `${entry.path}（${entry.why}）`))}` : '',\n  ].filter(Boolean)\n  return lines.length > 0 ? lines.join('\\n') : '没有文件与检查点不同'\n}\n\nconst describeResult = (result: RestoreResult): string =>\n  `改回 ${result.restored.length} 个，删除 ${result.removed.length} 个，找回 ${result.broughtBack.length} 个${\n    result.leftAlone.length > 0 ? `，未动 ${result.leftAlone.length} 个（${listed(result.leftAlone.map(entry => entry.path))}）` : ''}`\n\n/** Why checkpoints are off, in one line for the user. */\nexport function offText(code: CheckpointsOff, limits: { readonly maxFiles: number, readonly maxTotalMb: number, readonly timeoutMs: number }): string {\n  switch (code) {\n    case 'no_root': return '检查点已关闭：配置里没有 checkpoint.root。'\n    case 'no_index': return '检查点已关闭：DSH 没有挂载存储（storageDomain），无处记录检查点。'\n    case 'git_missing': return '检查点已关闭：这台机器上找不到 git。'\n    case 'xcode_license': return `检查点已关闭：${UNUSABLE_TEXT.xcode_license}。在终端用 sudo xcodebuild -license 同意后重启 DSH。`\n    case 'developer_tools_missing': return `检查点已关闭：${UNUSABLE_TEXT.developer_tools_missing}。用 xcode-select --install 安装后重启 DSH。`\n    case 'home_folder': return '这个文件夹是主目录或包含主目录，不拍检查点。在项目文件夹里启动会话才有检查点。'\n    case 'own_folder': return '这个文件夹在 sieve 自己存检查点的目录里，不拍检查点。'\n    case 'too_many_files': return `这个文件夹要拍的文件超过 ${limits.maxFiles} 个，不拍检查点；可以调高 checkpoint.maxFiles。`\n    case 'too_many_bytes': return `这个文件夹要拍的文件超过 ${limits.maxTotalMb} MB，不拍检查点；可以调高 checkpoint.maxTotalMb。`\n    case 'too_slow': return `列出这个文件夹的文件用了超过 ${Math.round(limits.timeoutMs / 1000)} 秒，不拍检查点。`\n  }\n}\n\n/** A rewind's file half: the snapshot of the present taken first, and what changed. */\ninterface FilesRewound {\n  readonly undo: string\n  readonly result: RestoreResult\n}\n\nexport interface RewindRequest {\n  /** The checkpoint number; the latest when absent. */\n  readonly id?: number\n  readonly scope: RewindScope\n  /** Rewind files changed after the agent's last change too; by default they are kept. */\n  readonly force: boolean\n  /** Say what would happen, change nothing. */\n  readonly preview: boolean\n}\n\nexport class CheckpointRuntime {\n  private readonly ctx: Context\n  private readonly host: Sieve\n  private readonly runtime: SessionRuntime\n  private readonly config: Sieve['config']['checkpoint']\n  private readonly run: GitRun\n  private readonly home: string\n  private readonly limits: ScanLimits\n  private readonly projects = new Map<string, Project>()\n  private readonly lives = new WeakMap<Agent, Live>()\n  private readonly lifetime = new AbortController()\n  /** Scans after the agent's changes that have not finished. */\n  private readonly noting = new Set<Promise<void>>()\n  index: CheckpointIndex | undefined\n  /** Off on this machine, for the rest of the process. */\n  private machineOff: CheckpointsOff | undefined\n\n  constructor(ctx: Context, host: Sieve, runtime: SessionRuntime, deps: CheckpointDeps = {}) {\n    this.ctx = ctx\n    this.host = host\n    this.runtime = runtime\n    this.config = host.config.checkpoint\n    this.home = deps.home ?? homedir()\n    this.run = deps.run ?? spawnGit('git', this.config.timeoutMs, this.lifetime.signal)\n    this.limits = { maxFiles: this.config.maxFiles, maxBytes: this.config.maxTotalMb * 1024 * 1024 }\n    if (this.config.root === '') this.machineOff = 'no_root'\n  }\n\n  /** Why the next snapshot of this folder would not be taken; undefined when it would. */\n  offFor(root: string): CheckpointsOff | undefined {\n    if (this.machineOff !== undefined) return this.machineOff\n    if (this.index === undefined) return 'no_index'\n    const project = this.projects.get(root)\n    if (project?.off !== undefined) return project.off\n    if (isWithin(root, this.home)) return 'home_folder'\n    return isWithin(this.config.root, root) ? 'own_folder' : undefined\n  }\n\n  /** The folder a session's tools work in now; undefined for a session without a project. */\n  rootOf(agent: Agent): string | undefined {\n    return this.ctx.get('workingDirectory')?.get(agent.session) ?? agent.session.header.cwd\n  }\n\n  live(agent: Agent): Live {\n    let state = this.lives.get(agent)\n    if (state === undefined) {\n      state = { turn: -1, taking: undefined, checkpoint: undefined, trouble: undefined, askedAbout: undefined, asked: 0, asking: false, proposed: undefined, queue: [] }\n      this.lives.set(agent, state)\n    }\n    return state\n  }\n\n  factsOf(agent: Agent): TurnFacts | undefined {\n    return this.ctx.sessionProjections.stateOf(agent.session, CHECKPOINT_STATE_KEY)\n  }\n\n  /** This turn's state, reset when a new turn began. */\n  turnOf(agent: Agent, facts: TurnFacts): Live {\n    const state = this.live(agent)\n    if (state.turn !== facts.turn) {\n      state.turn = facts.turn\n      state.taking = undefined\n      state.checkpoint = undefined\n      state.trouble = undefined\n      state.askedAbout = undefined\n      state.asked = 0\n    }\n    return state\n  }\n\n  /** The turn's snapshot, taken before its first change; a turn that only reads costs nothing. */\n  async ensure(agent: Agent): Promise<CheckpointRecord | undefined> {\n    const facts = this.factsOf(agent)\n    if (facts === undefined || facts.startSeq < 0) return undefined\n    const state = this.turnOf(agent, facts)\n    state.taking ??= this.take(agent, facts).then((record) => {\n      if (state.turn === facts.turn) state.checkpoint = record\n      return record\n    })\n    return state.taking\n  }\n\n  private async take(agent: Agent, facts: TurnFacts): Promise<CheckpointRecord | undefined> {\n    const root = this.rootOf(agent)\n    if (root === undefined || this.offFor(root) !== undefined) return undefined\n    const index = this.index\n    if (index === undefined) return undefined\n    const project = this.project(root)\n    const sessionId = agent.session.header.id\n    try {\n      const store = await this.open(project)\n      const id = index.nextId(sessionId)\n      const taken = await this.exclusive(project, () => snapshot(store, `${sessionId}/${id}`, this.limits))\n      const record: CheckpointRecord = {\n        id,\n        turn: facts.turn,\n        boundarySeq: facts.startSeq - 1,\n        commit: taken.commit,\n        root,\n        label: facts.label,\n        at: new Date().toISOString(),\n      }\n      await index.addCheckpoint(sessionId, record)\n      void index.setLastTree(sessionId, taken.tree)\n      return record\n    } catch (error) {\n      this.giveUp(project, error)\n      return undefined\n    }\n  }\n\n  /** After a call that may have changed files: what the agent left is what a later hand edit differs from. */\n  noteChange(agent: Agent): Promise<void> {\n    const work = this.scanAfter(agent)\n    this.noting.add(work)\n    void work.finally(() => this.noting.delete(work))\n    return work\n  }\n\n  /** Resolves once the scans and index writes started so far are done. */\n  async idle(): Promise<void> {\n    await Promise.all(this.noting)\n    await Promise.all([...this.projects.values()].map(project => project.chain))\n    await this.index?.drain()\n  }\n\n  private async scanAfter(agent: Agent): Promise<void> {\n    const state = this.live(agent)\n    const record = state.checkpoint\n    const index = this.index\n    if (record === undefined || index === undefined || this.offFor(record.root) !== undefined) return\n    const project = this.project(record.root)\n    try {\n      const store = await this.open(project)\n      const { tree } = await this.exclusive(project, () => scan(store, this.limits))\n      await index.setLastTree(agent.session.header.id, tree)\n    } catch (error) {\n      this.giveUp(project, error)\n    }\n  }\n\n  /** Checkpoints stop where git or the folder rules them out; the status says why. */\n  private giveUp(project: Project, error: unknown): void {\n    if (error instanceof GitMissing) this.machineOff ??= 'git_missing'\n    else if (error instanceof GitUnusable) this.machineOff ??= error.reason\n    else if (error instanceof SnapshotTooLarge) {\n      const codes = { files: 'too_many_files', bytes: 'too_many_bytes', slow: 'too_slow' } as const\n      project.off ??= codes[error.reason]\n    } else {\n      this.ctx.logger.warn(`sieve: no checkpoint for this turn (${clip(error instanceof Error ? error.message : String(error), 200)})`)\n    }\n  }\n\n  private project(root: string): Project {\n    let project = this.projects.get(root)\n    if (project === undefined) {\n      project = { root, store: undefined, chain: Promise.resolve(), busy: 0, off: undefined }\n      this.projects.set(root, project)\n    }\n    return project\n  }\n\n  private exclusive<T>(project: Project, work: () => Promise<T>): Promise<T> {\n    project.busy++\n    const next = project.chain.then(work, work).finally(() => { project.busy-- })\n    project.chain = next.catch(() => {})\n    return next\n  }\n\n  private open(project: Project): Promise<Store> {\n    project.store ??= this.exclusive(project, async () => {\n      const store = await openStore({\n        baseDir: this.config.root,\n        root: project.root,\n        run: this.run,\n        maxFileBytes: this.config.maxFileMb * 1024 * 1024,\n        ignore: [...BUILT_IN_IGNORES, ...this.config.ignore],\n        ownFolders: [this.config.root],\n      })\n      // Old snapshots go when a project is first used; their objects follow in the background.\n      const dropped = await prune(store, { keep: this.config.keep, maxAgeDays: this.config.maxAgeDays }).catch(() => 0)\n      if (dropped > 0) void this.exclusive(project, () => collectGarbage(store)).catch(() => {})\n      return store\n    })\n    const opening = project.store\n    // A failed open is tried again next time.\n    opening.catch(() => { if (project.store === opening) project.store = undefined })\n    return opening\n  }\n\n  /** Repositories of projects nobody used for `maxAgeDays`, and of folders that are off limits now. */\n  sweep(): void {\n    if (this.config.root === '') return\n    sweepProjects(this.config.root, this.config.maxAgeDays, Date.now(), root => isWithin(root, this.home) || isWithin(this.config.root, root))\n  }\n\n  /** Waits briefly for running git commands, then clears what they may have left locked. */\n  async dispose(): Promise<void> {\n    this.lifetime.abort(new Error('sieve checkpoints unloaded'))\n    const wasBusy = [...this.projects.values()].some(project => project.busy > 0)\n    await Promise.race([\n      Promise.all([...this.projects.values()].map(project => project.chain)),\n      new Promise((resolve) => { setTimeout(resolve, 3000).unref() }),\n    ])\n    for (const project of this.projects.values()) {\n      const store = await project.store?.catch(() => undefined)\n      if (store !== undefined) releaseLocks(store, wasBusy && project.busy > 0 ? 0 : 120_000)\n    }\n  }\n\n  // --- the judged proposal -------------------------------------------------\n\n  /** Why `turn.rewind` is asked now, if it is; `key` stays the same while the cause does. */\n  private trigger(state: Live, facts: TurnFacts): { readonly key: string, readonly text: string } | undefined {\n    if (state.trouble !== undefined) return { key: state.trouble, text: state.trouble }\n    const failing = Object.entries(facts.failures).find(([, count]) => count >= this.config.failures)\n    return failing === undefined ? undefined : { key: `failing: ${failing[0]}`, text: `the same failing command ran ${failing[1]} times: ${clip(failing[0], 120)}` }\n  }\n\n  /** At a step boundary: ask about a new trigger in the background, deliver a proposal that came in. */\n  boundary(agent: Agent, turn: number): ReturnType<typeof sieveNotice>[] {\n    const facts = this.factsOf(agent)\n    if (facts === undefined) return []\n    const state = this.turnOf(agent, facts)\n    const mode = this.host.modeOf(turnRewind.id, agent.session.header.id)\n    const cause = this.trigger(state, facts)\n    const checkpoint = state.checkpoint\n    if (this.config.propose && mode !== 'off' && cause !== undefined && checkpoint !== undefined\n      && state.askedAbout !== cause.key && state.asked < MAX_ASKED && !state.asking) {\n      const trigger = cause.text\n      state.askedAbout = cause.key\n      state.asked++\n      state.asking = true\n      const engine = this.runtime.for(agent)\n      void engine.engine.decide(turnRewind, {\n        goal: clip(this.ctx.get('goals')?.get(agent)?.objective ?? checkpoint.label, 600),\n        recentSteps: facts.steps,\n        trigger,\n        editsSinceCheckpoint: facts.edits,\n        ...(facts.lastCheckFailed === null ? {} : { lastCheckFailed: facts.lastCheckFailed }),\n      }, { signal: engine.controller.signal, applied: false, origin: { turn, checkpoint: checkpoint.id } }).then((value: Decision<RewindOutcome>) => {\n        if (value.source !== 'judge' || value.outcome !== 'propose' || mode !== 'active') return\n        state.proposed = { id: checkpoint.id, trigger, at: new Date().toISOString() }\n        state.queue.push({\n          message: sieveNotice('rewind', `This approach looks like a dead end (${trigger}). Stop repeating it: tell the user what you tried and why it fails. They can put the files and the conversation back to checkpoint #${checkpoint.id}, before \"${checkpoint.label}\", with /sieve rewind ${checkpoint.id}.`, `dead end: ${clip(trigger, 120)}`),\n          turn,\n          ledgerId: value.ledgerId,\n        })\n        this.ctx.logger.info(`sieve: proposed going back to checkpoint #${checkpoint.id} in session ${agent.session.header.id} (${trigger})`)\n      }).catch(() => {}).finally(() => { state.asking = false })\n    }\n    const due = state.queue.splice(0).filter(item => item.turn === turn)\n    for (const item of due) {\n      if (item.ledgerId !== undefined) void this.host.track(this.host.annotate(agent.session.header.id, item.ledgerId, { applied: true }))\n    }\n    return due.map(item => item.message)\n  }\n\n  /** A rewind's notice waiting for this session's next step, taken off the index. */\n  takeNotice(agent: Agent): ReturnType<typeof sieveNotice> | undefined {\n    const sessionId = agent.session.header.id\n    const notice = this.index?.of(sessionId).notice\n    if (notice === undefined || notice === null) return undefined\n    void this.index?.setNotice(sessionId, null)\n    return sieveNotice('rewind', notice.text, notice.summary)\n  }\n\n  // --- the commands --------------------------------------------------------\n\n  private refusal(root: string): string | undefined {\n    const off = this.offFor(root)\n    if (off === undefined) return undefined\n    // A folder that went over a size limit still opens the snapshots it already has.\n    if (off === 'too_many_files' || off === 'too_many_bytes' || off === 'too_slow') return undefined\n    return offText(off, this.config)\n  }\n\n  /** `/sieve checkpoints`: newest first, with how many files changed since each. */\n  async listText(agent: Agent): Promise<string> {\n    const sessionId = agent.session.header.id\n    const records = [...(this.index?.of(sessionId).checkpoints ?? [])].reverse()\n    const machine = this.machineOff ?? (this.index === undefined ? 'no_index' : undefined)\n    if (machine !== undefined) return offText(machine, this.config)\n    if (records.length === 0) {\n      const root = this.rootOf(agent)\n      const off = root === undefined ? undefined : this.offFor(root)\n      return off === undefined ? '还没有检查点：每个回合第一次修改文件之前拍一个。' : offText(off, this.config)\n    }\n    const rows: string[] = []\n    const trees = new Map<string, string>()\n    for (const record of records.slice(0, 20)) {\n      let changed: string\n      try {\n        const project = this.project(record.root)\n        const store = await this.open(project)\n        let tree = trees.get(record.root)\n        if (tree === undefined) {\n          tree = (await this.exclusive(project, () => scan(store))).tree\n          trees.set(record.root, tree)\n        }\n        const now = tree\n        changed = await hasCommit(store, record.commit)\n          ? `之后改了 ${(await this.exclusive(project, () => diff(store, record.commit, now))).length} 个文件`\n          : '快照已清理'\n      } catch (error) {\n        this.giveUp(this.project(record.root), error)\n        changed = '无法读取'\n      }\n      rows.push(`#${record.id}  第 ${record.turn} 回合  ${record.at.slice(0, 19).replace('T', ' ')}  ${changed}  “${record.label}”`)\n    }\n    return `${rows.join('\\n')}\\n/sieve rewind [序号] [files|conversation|both] [preview|force] 回到某个检查点；/sieve rewind undo 撤销上一次回退。`\n  }\n\n  /** Files a rewind would change that somebody changed after the agent's last change: probably the user, by hand. */\n  private async handEdited(store: Store, project: Project, plan: RestorePlan, nowTree: string, lastTree: string | null): Promise<string[]> {\n    const planned = new Set([...plan.restore, ...plan.remove, ...plan.bringBack])\n    // Without a record of the agent's last change nobody can tell, so every file counts as possibly the user's.\n    if (lastTree === null) return [...planned]\n    const since = await this.exclusive(project, () => diff(store, lastTree, nowTree)).catch(() => undefined)\n    return since === undefined ? [...planned] : since.map(change => change.path).filter(path => planned.has(path))\n  }\n\n  /** `/sieve rewind`: the files, the conversation, or both, back to a checkpoint. */\n  async rewind(agent: Agent, request: RewindRequest, signal: AbortSignal): Promise<{ ok: boolean, text: string }> {\n    if (agent.status === 'running') return { ok: false, text: '代理还在运行。先停下它，再回退。' }\n    const index = this.index\n    if (index === undefined) return { ok: false, text: offText('no_index', this.config) }\n    const sessionId = agent.session.header.id\n    const own = index.of(sessionId)\n    const checkpoint = request.id === undefined ? own.checkpoints.at(-1) : own.checkpoints.find(record => record.id === request.id)\n    if (checkpoint === undefined) {\n      return { ok: false, text: request.id === undefined ? '还没有检查点。' : `没有 #${request.id} 号检查点。/sieve checkpoints 列出全部。` }\n    }\n    // Without these the conversation cannot be forked: say so before any file is touched.\n    if (request.scope !== 'files' && !request.preview && this.forkable(checkpoint)\n      && (this.ctx.get('sessionQuery') === undefined || this.ctx.get('agents') === undefined)) {\n      return { ok: false, text: 'DSH 没有挂载 sessionQuery 或 agents 服务，对话不能分叉；什么也没动。只回退文件用 /sieve rewind files。' }\n    }\n    const lines: string[] = []\n    let files: FilesRewound | undefined\n    if (request.scope !== 'conversation') {\n      const refused = this.refusal(checkpoint.root)\n      if (refused !== undefined) return { ok: false, text: refused }\n      const project = this.project(checkpoint.root)\n      const store = await this.open(project)\n      if (!await hasCommit(store, checkpoint.commit)) return { ok: false, text: `#${checkpoint.id} 的快照已被清理。` }\n      const now = await this.exclusive(project, () => scan(store))\n      const plan = await this.exclusive(project, () => planRestore(store, checkpoint.commit, now.tree))\n      const byHand = await this.handEdited(store, project, plan, now.tree, own.lastTree)\n      const keep = new Set(request.force ? [] : byHand)\n      signal.throwIfAborted()\n      if (request.preview) {\n        lines.push(`回到 #${checkpoint.id}（第 ${checkpoint.turn} 回合之前，“${checkpoint.label}”）时，文件会这样变：`, describePlan(plan, keep))\n        if (keep.size > 0) lines.push('这些文件在代理最后一次修改之后又被改过（多半是手动），默认保留；加 force 一并回退，撤销快照可以找回。')\n      } else {\n        const undo = await this.exclusive(project, () => snapshot(store, `${sessionId}/undo-${Date.now()}`))\n        const result = await this.exclusive(project, () => applyRestore(store, plan, keep))\n        const after = await this.exclusive(project, () => scan(store))\n        void index.setLastTree(sessionId, after.tree)\n        files = { undo: undo.commit, result }\n        lines.push(`文件已回到 #${checkpoint.id}：${describeResult(result)}。/sieve rewind undo 可以撤销。`)\n      }\n    }\n    if (request.scope === 'files' || request.preview) {\n      if (request.preview && request.scope !== 'files') lines.push(this.forkable(checkpoint) ? `对话会分叉成一个新会话，停在第 ${checkpoint.turn} 回合之前；原会话不变。` : '这个检查点在会话开头，对话不能再往前退。')\n      if (files !== undefined) await this.filesRewound(sessionId, checkpoint, files)\n      return { ok: true, text: lines.join('\\n') }\n    }\n    if (!this.forkable(checkpoint)) {\n      if (files !== undefined) await this.filesRewound(sessionId, checkpoint, files)\n      return { ok: files !== undefined, text: [...lines, '这个检查点在会话开头，对话不能再往前退。'].join('\\n') }\n    }\n    let forked: string\n    try {\n      forked = await this.fork(agent, checkpoint, signal)\n    } catch (error) {\n      const why = clip(error instanceof Error ? error.message : String(error), 200)\n      if (files === undefined) return { ok: false, text: [...lines, `对话没能分叉（${why}），什么也没动。`].join('\\n') }\n      // The files went back already: the rewind stays one of the files, which undo can take back and this session is told about.\n      await this.filesRewound(sessionId, checkpoint, files)\n      return { ok: false, text: [...lines, `对话没能分叉（${why}）：只回退了文件，对话仍在这个会话里。`].join('\\n') }\n    }\n    this.record(sessionId, checkpoint, request.scope, files?.undo ?? null, forked)\n    // The new session starts with the checkpoints of the history it inherits, can undo this rewind, and is told what was abandoned.\n    await index.seed(forked, {\n      v: 1,\n      checkpoints: own.checkpoints.filter(record => record.id <= checkpoint.id),\n      rewinds: [rewindRecord(checkpoint, request.scope, files?.undo ?? null, forked)],\n      lastTree: own.lastTree,\n      notice: {\n        text: [\n          `The user went back to before \"${checkpoint.label}\". An attempt made after this point was abandoned${files === undefined ? '' : ' and its file changes were undone'}. Take a different approach.`,\n          files === undefined ? 'The files were left as they are: they may still hold changes from the abandoned attempt.' : changedText(files.result),\n        ].filter(Boolean).join('\\n'),\n        summary: `rewound to before #${checkpoint.id}`,\n      },\n    })\n    lines.push(`对话已分叉到新会话 ${forked}，停在第 ${checkpoint.turn} 回合之前（“${checkpoint.label}”）；原会话不变。打开新会话继续。`)\n    if (request.scope === 'conversation') lines.push('文件没有动：它们仍带着之后的修改。')\n    return { ok: true, text: lines.join('\\n') }\n  }\n\n  private forkable(checkpoint: CheckpointRecord): boolean {\n    return checkpoint.boundarySeq >= 0\n  }\n\n  /** The files went back and the conversation stays: recorded so undo can take it back, and the session is told at its next step. */\n  private async filesRewound(sessionId: string, checkpoint: CheckpointRecord, files: FilesRewound): Promise<void> {\n    this.record(sessionId, checkpoint, 'files', files.undo, null)\n    await this.index?.setNotice(sessionId, {\n      text: [\n        `The user put the files back to checkpoint #${checkpoint.id}, as they were before \"${checkpoint.label}\". What was changed since is undone: do not assume those edits exist.`,\n        changedText(files.result),\n      ].filter(Boolean).join('\\n'),\n      summary: `files back to #${checkpoint.id}`,\n    })\n  }\n\n  private record(sessionId: string, checkpoint: CheckpointRecord, scope: RewindScope, undo: string | null, forked: string | null): void {\n    void this.index?.addRewind(sessionId, rewindRecord(checkpoint, scope, undo, forked))\n  }\n\n  /** DSH's fork path (C7): the history up to the checkpoint seeds a new, persisted session. */\n  private async fork(agent: Agent, checkpoint: CheckpointRecord, signal: AbortSignal): Promise<string> {\n    const query = this.ctx.get('sessionQuery')\n    const agents = this.ctx.get('agents')\n    if (query === undefined || agents === undefined) throw new Error('DSH has no sessionQuery or agents service mounted; the conversation cannot be forked')\n    const source = agent.session.header\n    using observed = await query.observeSession(source.id)\n    signal.throwIfAborted()\n    const seed = buildForkSeed(observed.events, SessionSeq(checkpoint.boundarySeq))\n    const childId = SessionId(`session-${randomUUID()}`)\n    const child = await agents.create({\n      sessionId: childId,\n      seed,\n      inheritedEventCount: SessionLogOffset(checkpoint.boundarySeq + 1),\n      meta: { ...(source.cwd === undefined ? {} : { cwd: source.cwd }), parentSession: source.id, isSeeded: true },\n      agentOptions: { ...agent.options },\n    })\n    // Nobody drives it here: the person opens it, and DSH resumes it then.\n    await child.dispose()\n    return childId\n  }\n\n  /** `/sieve rewind undo`: the files as they were right before the last rewind. */\n  async undo(agent: Agent, signal: AbortSignal): Promise<{ ok: boolean, text: string }> {\n    if (agent.status === 'running') return { ok: false, text: '代理还在运行。先停下它，再撤销。' }\n    const index = this.index\n    if (index === undefined) return { ok: false, text: offText('no_index', this.config) }\n    const sessionId = agent.session.header.id\n    const last = index.of(sessionId).rewinds.at(-1)\n    if (last === undefined) return { ok: false, text: '这个会话没有可撤销的回退。' }\n    if (last.undo === null) {\n      return { ok: false, text: last.forked === null ? '上一次回退没有动文件。' : `上一次回退只分叉了对话；原来的对话还在，回到原会话即可。` }\n    }\n    const undoCommit = last.undo\n    const refused = this.refusal(last.root)\n    if (refused !== undefined) return { ok: false, text: refused }\n    const project = this.project(last.root)\n    const store = await this.open(project)\n    if (!await hasCommit(store, undoCommit)) return { ok: false, text: '回退之前拍的快照已被清理。' }\n    const now = await this.exclusive(project, () => scan(store))\n    const plan = await this.exclusive(project, () => planRestore(store, undoCommit, now.tree))\n    signal.throwIfAborted()\n    const redo = await this.exclusive(project, () => snapshot(store, `${sessionId}/undo-${Date.now()}`))\n    const result = await this.exclusive(project, () => applyRestore(store, plan, new Set()))\n    const after = await this.exclusive(project, () => scan(store))\n    void index.setLastTree(sessionId, after.tree)\n    void index.addRewind(sessionId, { to: 'undo', scope: 'files', undo: redo.commit, root: last.root, forked: null, at: new Date().toISOString() })\n    await index.setNotice(sessionId, {\n      text: ['The user undid the last rewind: the files are back as they were right before it.', changedText(result)].filter(Boolean).join('\\n'),\n      summary: 'rewind undone',\n    })\n    return { ok: true, text: `已撤销上一次回退：${describeResult(result)}。` }\n  }\n\n  status(sessionId: string, agent: Agent | undefined): SieveCheckpointStatus {\n    const own = this.index?.of(sessionId)\n    const latest = own?.checkpoints.at(-1)\n    const root = agent === undefined ? undefined : this.rootOf(agent)\n    const off = root === undefined ? (this.machineOff ?? (this.index === undefined ? 'no_index' : undefined)) : this.offFor(root)\n    const proposed = agent === undefined ? undefined : this.lives.get(agent)?.proposed\n    return {\n      enabled: off === undefined,\n      off: off === undefined ? null : offText(off, this.config),\n      checkpoints: own?.checkpoints.length ?? 0,\n      latest: latest === undefined ? null : { id: latest.id, turn: latest.turn, label: latest.label, at: latest.at },\n      rewinds: own?.rewinds.length ?? 0,\n      proposed: proposed ?? null,\n    }\n  }\n}\n\nfunction rewindRecord(checkpoint: CheckpointRecord, scope: RewindScope, undo: string | null, forked: string | null): RewindRecord {\n  return { to: checkpoint.id, scope, undo, root: checkpoint.root, forked, at: new Date().toISOString() }\n}\n\nfunction changedText(result: RestoreResult): string {\n  const changed = [...result.restored, ...result.removed, ...result.broughtBack]\n  const kept = result.leftAlone.map(entry => entry.path)\n  return [\n    changed.length > 0 ? `Files put back: ${listed(changed)}` : '',\n    kept.length > 0 ? `Left as they are: ${listed(kept)}` : '',\n  ].filter(Boolean).join('\\n')\n}\n\n/** Mounts checkpoints on a `sieve-runtime` child; the caller keeps the runtime for `/sieve rewind`. */\nexport function registerCheckpoint(ctx: Context, host: Sieve, runtime: SessionRuntime, deps: CheckpointDeps = {}): CheckpointRuntime {\n  registerTurnFacts(ctx)\n  const checkpoints = new CheckpointRuntime(ctx, host, runtime, deps)\n  // A sub-agent works inside its parent's turn: the parent's checkpoint covers what it changes. The hive watches its bees.\n  const watched = (agent: Agent): boolean => agent.session.header.origin !== 'subagent' && host.hive?.isBee(agent) !== true\n  const mutating = new WeakSet<object>()\n\n  ctx.effect(() => {\n    try { checkpoints.sweep() } catch { /* bookkeeping: a sweep that fails waits for the next start */ }\n    return () => checkpoints.dispose()\n  }, 'sieve.checkpoints')\n\n  ctx.plugin({\n    name: 'sieve-checkpoint-index',\n    inject: ['storageDomain'],\n    apply: async (child: Context) => {\n      const domain = await child.storageDomain.open(checkpointDomain)\n      const index = new CheckpointIndex(domain.table('sessions'), child.logger)\n      checkpoints.index = index\n      child.effect(() => async () => {\n        if (checkpoints.index === index) checkpoints.index = undefined\n        await index.drain()\n        await domain.close()\n      }, 'sieve.checkpoint-index')\n    },\n  })\n\n  ctx.on('tools/pre-execute', async (exec, next) => {\n    const agent = exec.agent\n    const input = typeof exec.arguments === 'object' && exec.arguments !== null ? exec.arguments as Record<string, unknown> : {}\n    if (agent !== undefined && watched(agent) && isMutatingCall(exec.name, input)) {\n      mutating.add(exec)\n      // A cancelled call does not wait for the snapshot; the snapshot itself goes on for the turn's next change.\n      try { await untilAbort(checkpoints.ensure(agent), exec.signal) } catch { /* no checkpoint: the call runs all the same */ }\n    }\n    return next()\n  })\n\n  ctx.on('tools/result', (exec) => {\n    if (!mutating.has(exec) || exec.agent === undefined) return\n    mutating.delete(exec)\n    void checkpoints.noteChange(exec.agent)\n  })\n\n  ctx.on('sieve/trouble', (agent, kind, detail) => {\n    const facts = checkpoints.factsOf(agent)\n    if (facts === undefined || !watched(agent)) return\n    checkpoints.turnOf(agent, facts).trouble = `the monitor saw ${kind === 'drift' ? 'a drift from the goal' : kind === 'stalled' ? 'a stalled loop' : 'a loop'}: ${clip(detail, 120)}`\n  })\n\n  ctx.on('agent/pre-step', async (payload, next) => {\n    const decision = await next()\n    const { agent, turn } = payload\n    if (decision.kind !== 'enter' || !watched(agent)) return decision\n    try {\n      // A rewind's notice goes before the request it came with: what happened, then what is asked.\n      const pending = checkpoints.takeNotice(agent)\n      const told = checkpoints.boundary(agent, turn)\n      if (pending === undefined && told.length === 0) return decision\n      return { ...decision, messages: [...(pending === undefined ? [] : [pending]), ...decision.messages, ...told] }\n    } catch {\n      ctx.logger.warn('sieve: checkpoints failed at a step boundary; nothing added')\n      return decision\n    }\n  })\n\n  return checkpoints\n}\n"
    },
    {
      "path": "packages/dsh-sieve/src/features/hive/index.ts",
      "content": "/**\n * The hive: the `hive` tool, the `/hive` command, and the hooks that make a\n * bee of a child Agent. Bees are DSH in-process subagents under ids reserved\n * before they start, so the hooks know a bee from its first event:\n *\n * - `agent/created`: its file-editing and delegation tools are hidden and its\n *   session's sandbox mode set to read-only (bash writes are fenced only where\n *   a sandbox runner is active);\n * - `session/event`: each finished step goes to the gates (`HiveMember`);\n * - `agent/pre-step`: what the gates accepted for it enters its next step;\n * - `agent/turn-stopping`: the last call;\n * - `tools/pre-execute`: tools of a bee told to wrap up are closed;\n * - `agent/assistant-stream`: liveness, for the watchdog.\n *\n * Ported from mu `packages/kyrn-judge/src/extension/features/hive.ts`.\n * Contains MIT-licensed third-party code, see THIRD_PARTY_NOTICES.md.\n * @module\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { CommandResult } from '@deepseek-ai/dsh-commands'\nimport { createUserMessage } from '@deepseek-ai/dsh-llm'\nimport { setSandboxMode } from '@deepseek-ai/dsh-sandbox-policy'\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { DecisionEngine } from '../../judge/engine.ts'\nimport { hiveRequest, parseHiveArgs } from '../../judge/hive/request.ts'\nimport { summarizeBoard } from '../../judge/hive/report.ts'\nimport { clip } from '../../judge/hive/member.ts'\nimport { FILE_WRITE_TOOLS } from '../../judge/monitor/mutating.ts'\nimport type { ResolvedConfig } from '../../runtime/config.ts'\nimport { Bee, HiveRun } from './run.ts'\nimport type { BeeRequest, HiveHooks } from './run.ts'\nimport { HiveStore, hiveDomain } from './store.ts'\nimport type { HiveRunRecord } from './store.ts'\n\nexport const HIVE_TOOL = 'hive'\n/** Tools that start more agents or worktrees: a bee investigates alone. */\nexport const DELEGATION_TOOLS = ['subagent', 'subagent_fork', 'spawn_teammate', 'create_worktree', HIVE_TOOL] as const\nconst BEE_DENIED: readonly string[] = [...FILE_WRITE_TOOLS, ...DELEGATION_TOOLS]\n/** How often a running hive's record is written for the live view. */\nconst SAVE_EVERY_MS = 2000\nconst MIN_BEES = 2\n\nexport interface HiveHost {\n  readonly config: ResolvedConfig\n  engineFor(agent: Agent): DecisionEngine\n}\n\nconst DESCRIPTION = [\n  'Run several read-only investigators (\"bees\") on one problem at the same time, each from its own angle, and get back every report plus a board of their findings.',\n  'Between their steps a judge model passes each bee only the others\\' findings that bear on its angle, corrections to findings it was given, and disputes; bees spend nothing on sharing, and none is flooded with what the others saw.',\n  'Use it for a question whose angles bear on each other (an intermittent failure: reproduce it, read the history, read the configuration). Not for a single lookup, and not for changes: bees cannot edit files.',\n  'Findings on the board are marked confirmed, corrected or disputed; weigh them accordingly. Each bee stays reachable with send_message after the hive returns.',\n].join(' ')\n\n/** The bees of running hives, the runs themselves, and where finished runs are kept. */\nexport class HiveRuntime {\n  private readonly bees = new Map<SessionId, Bee>()\n  /** Every bee of this plugin's lifetime: a bee messaged after its hive resumes with its tools hidden again. */\n  private readonly readOnly = new Set<SessionId>()\n  private readonly live = new Map<string, HiveRun>()\n  private readonly saves = new Map<string, ReturnType<typeof setTimeout>>()\n  private readonly lifetime = new AbortController()\n  private readonly running = new Set<Promise<unknown>>()\n  store: HiveStore | undefined\n\n  readonly hooks: HiveHooks = {\n    enroll: (bee) => {\n      this.bees.set(bee.childId, bee)\n      this.readOnly.add(bee.childId)\n    },\n    release: (bee) => {\n      if (this.bees.get(bee.childId) === bee) this.bees.delete(bee.childId)\n    },\n    changed: run => this.schedule(run),\n  }\n\n  get signal(): AbortSignal {\n    return this.lifetime.signal\n  }\n\n  beeOf(agent: Agent): Bee | undefined {\n    return this.bees.get(agent.session.header.id)\n  }\n\n  beeIn(sessionId: SessionId): Bee | undefined {\n    return this.bees.get(sessionId)\n  }\n\n  /**\n   * Whether the agent is a bee, of a hive of this process or of a stored run:\n   * after a restart a bee messaged again is a child of the session that ran\n   * its hive, and only the stored runs (the latest `HIVE_SESSION_CAP`) know it.\n   */\n  isBee(agent: Agent): boolean {\n    const header = agent.session.header\n    if (this.readOnly.has(header.id)) return true\n    if (header.origin !== 'subagent' || header.parentSession === undefined) return false\n    const stored = this.store?.runs(header.parentSession).some(run => run.bees.some(bee => bee.childId === header.id)) === true\n    if (stored) this.readOnly.add(header.id)\n    return stored\n  }\n\n  /** A session's running hives. */\n  liveRuns(sessionId: SessionId): HiveRun[] {\n    return [...this.live.values()].filter(run => run.parent.session.header.id === sessionId)\n  }\n\n  /** A session's hives, oldest first: the stored ones, with the running ones as they are now. */\n  records(sessionId: SessionId): HiveRunRecord[] {\n    const live = this.liveRuns(sessionId).map(run => run.record())\n    const ids = new Set(live.map(run => run.id))\n    return [...(this.store?.runs(sessionId) ?? []).filter(run => !ids.has(run.id)), ...live]\n  }\n\n  /** Run one hive to its end. */\n  async run(run: HiveRun, bees: readonly BeeRequest[]): Promise<string> {\n    this.live.set(run.id, run)\n    const work = run.execute(bees)\n    this.running.add(work)\n    try {\n      return await work\n    } finally {\n      this.running.delete(work)\n      const timer = this.saves.get(run.id)\n      if (timer !== undefined) clearTimeout(timer)\n      this.saves.delete(run.id)\n      await this.store?.save(run.record())\n      this.live.delete(run.id)\n    }\n  }\n\n  private schedule(run: HiveRun): void {\n    if (this.store === undefined || this.saves.has(run.id) || run.status !== 'running') return\n    this.saves.set(run.id, setTimeout(() => {\n      this.saves.delete(run.id)\n      if (this.live.has(run.id)) void this.store?.save(run.record())\n    }, SAVE_EVERY_MS))\n  }\n\n  /** Unloading stops every hive and waits for its bees to stop. */\n  async close(): Promise<void> {\n    this.lifetime.abort(new Error('sieve unloaded'))\n    for (const run of this.live.values()) run.stopBees(undefined, 'sieve unloaded')\n    await Promise.allSettled(this.running)\n    for (const timer of this.saves.values()) clearTimeout(timer)\n    this.saves.clear()\n  }\n}\n\nexport function registerHive(ctx: Context, host: HiveHost, runtime: HiveRuntime): void {\n  const config = host.config.hive\n  ctx.effect(() => () => runtime.close(), 'sieve.hive')\n\n  ctx.on('agent/created', ({ agent, source }) => {\n    if (!runtime.isBee(agent)) return undefined\n    runtime.beeOf(agent)?.attach(agent)\n    // `restrict` accepts only names registered globally; anything else is denied by name in `tools/pre-execute`.\n    const hidden = BEE_DENIED.filter(name => ctx.tools.get(name) !== undefined)\n    if (hidden.length > 0) agent.ctx.tools.restrict({ deny: hidden })\n    // The mode is a native session event: it holds when the bee is resumed later.\n    if (source !== 'resume' && ctx.get('sandboxPolicy') !== undefined) setSandboxMode(agent.session, 'read-only')\n    return undefined\n  })\n\n  ctx.on('session/event', (session, event) => {\n    runtime.beeIn(session.header.id)?.observe(event)\n  })\n\n  ctx.on('agent/assistant-stream', ({ agent }) => {\n    runtime.beeOf(agent)?.touch()\n  })\n\n  // Inbox delivery at the step boundary: `agent.inject` from a `session/event` observer would re-enter the session append.\n  ctx.on('agent/pre-step', async ({ agent }, next) => {\n    const decision = await next()\n    if (decision.kind !== 'enter') return decision\n    const told = runtime.beeOf(agent)?.boundary()\n    return told === undefined ? decision : { ...decision, messages: [...decision.messages, told] }\n  })\n\n  ctx.on('agent/turn-stopping', async ({ agent, signal }) => {\n    await runtime.beeOf(agent)?.lastCall(agent, signal)\n  })\n\n  ctx.on('tools/pre-execute', async (exec, next) => {\n    const agent = exec.agent\n    if (agent === undefined || !runtime.isBee(agent)) return next()\n    if (BEE_DENIED.includes(exec.name)) return { kind: 'deny', reason: `${exec.name} is not available to a hive investigator: investigate and report, change nothing.` }\n    const reason = runtime.beeOf(agent)?.closedReason\n    if (reason !== undefined) return { kind: 'deny', reason }\n    return next()\n  }, { prepend: true })\n\n  ctx.tools.register(defineTool({\n    name: HIVE_TOOL,\n    description: DESCRIPTION,\n    parameters: {\n      goal: {\n        type: 'string',\n        required: true,\n        description: 'The problem, as the bees should read it: what is known, what a complete answer must contain.',\n      },\n      bees: {\n        type: 'array',\n        required: true,\n        description: `${MIN_BEES} to ${config.maxBees} investigators, each with a different angle on the same problem.`,\n        items: {\n          type: 'object',\n          additionalProperties: false,\n          properties: {\n            name: { type: 'string', required: true, description: 'Short name after its angle, e.g. \"repro\" or \"history\".' },\n            focus: { type: 'string', required: true, description: 'What this bee looks at and how, so that what it finds can confirm, correct or advance the others.' },\n          },\n        },\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          hive: { type: 'string', required: true },\n          status: { type: 'string', required: true },\n          bees: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                name: { type: 'string', required: true },\n                childId: { type: 'string', required: true },\n                status: { type: 'string', required: true },\n                placement: { type: 'string', required: true },\n              },\n            },\n          },\n          report: { type: 'string', required: true },\n        },\n      },\n      render: (_args, value) => [{ type: 'text', text: value.report }],\n    },\n    async execute(args, exec) {\n      const parent = exec.agent\n      if (parent === undefined) throw new Error('hive requires an owning agent session')\n      if (runtime.isBee(parent)) throw new Error('a bee cannot start a hive')\n      const goal = args.goal.trim()\n      if (goal === '') throw new Error('goal is empty')\n      const bees = args.bees.map(bee => ({ name: bee.name, focus: bee.focus.trim() })).filter(bee => bee.focus !== '')\n      if (bees.length < MIN_BEES) throw new Error(`a hive needs at least ${MIN_BEES} bees with a focus`)\n      const run = new HiveRun({\n        ctx,\n        parent,\n        callId: exec.callId,\n        goal,\n        config,\n        engine: host.engineFor(parent),\n        hooks: runtime.hooks,\n        signal: AbortSignal.any([exec.signal, runtime.signal]),\n      })\n      const report = await runtime.run(run, bees)\n      return {\n        hive: run.id,\n        status: run.status,\n        bees: run.bees.map(bee => ({ name: bee.name, childId: bee.childId, status: bee.status, placement: bee.placement.label })),\n        report,\n      }\n    },\n  }))\n\n  ctx.plugin({\n    name: 'sieve-hive-store',\n    inject: ['storageDomain'],\n    apply: async (child: Context) => {\n      const domain = await child.storageDomain.open(hiveDomain)\n      const store = new HiveStore(domain.table('sessions'), child.logger)\n      runtime.store = store\n      child.effect(() => async () => {\n        if (runtime.store === store) runtime.store = undefined\n        await store.drain()\n        await domain.close()\n      }, 'sieve.hive-store')\n    },\n  })\n\n  ctx.plugin({\n    name: 'sieve-hive-command',\n    inject: ['commands'],\n    apply: (child: Context) => { registerHiveCommand(child, runtime) },\n  })\n}\n\nconst USAGE = '/hive <问题> | status | stop [蜂] | kill [蜂]'\n\nfunction seconds(from: number, to: number): string {\n  return `${Math.max(0, Math.round((to - from) / 1000))} 秒`\n}\n\n/** `/hive` for a person: start one by asking, or watch and control the running ones. */\nexport function hiveStatusText(runs: readonly HiveRun[]): string {\n  if (runs.length === 0) return '当前会话没有正在运行的 hive。'\n  return runs.map((run) => {\n    const board = summarizeBoard(run.board.snapshot())\n    return [\n      `hive ${run.id}：运行 ${seconds(run.startedAt, run.now())}；目标：${clip(run.goal, 120)}`,\n      ...run.bees.map(bee => `- ${bee.name}${bee.verifier ? '（核验）' : ''} [${bee.placement.label}]：${bee.status}${bee.said === '' ? '' : `；最近：${clip(bee.said, 120)}`}`),\n      `看板：${board.notes} 条笔记，${board.deliveries} 次投递，${board.corrections} 次更正，${board.conflicts} 个争议；判断 ${board.judged} 次`,\n    ].join('\\n')\n  }).join('\\n\\n')\n}\n\nexport function registerHiveCommand(ctx: Context, runtime: HiveRuntime): void {\n  ctx.commands.register({\n    name: 'hive',\n    description: '让几只只读的蜂并行调查一个问题；不带问题时显示或控制正在运行的 hive',\n    input: { hint: USAGE },\n    handler: ({ agent, rawInput, signal }): CommandResult => {\n      signal.throwIfAborted()\n      const args = parseHiveArgs(rawInput)\n      if (args.kind === 'question') {\n        agent.followup(createUserMessage({ content: [{ type: 'text', text: hiveRequest(args.question) }], source: { kind: 'user' } }))\n        return { kind: 'success', text: '已让主模型发起 hive。' }\n      }\n      const runs = runtime.liveRuns(agent.session.header.id)\n      if (args.kind === 'status') return { kind: 'success', text: hiveStatusText(runs) }\n      if (runs.length === 0) return { kind: 'error', text: '当前会话没有正在运行的 hive。' }\n      const count = runs.reduce((total, run) => total + (args.verb === 'kill'\n        ? run.stopBees(args.name, 'stopped by the user')\n        : run.wrapUpBees(args.name, 'the user asked for the reports now')), 0)\n      if (count === 0) return { kind: 'error', text: args.name === undefined ? '没有可操作的蜂。' : `没有名为 ${args.name} 的运行中的蜂。` }\n      return { kind: 'success', text: args.verb === 'kill' ? `已停止 ${count} 只蜂；它们已有的报告照常交回。` : `已让 ${count} 只蜂收尾：工具关闭，立即交报告。` }\n    },\n  })\n}\n"
